#!/usr/bin/env node
// L1 source picker for the article-level2 (L1→L2) skill — the read half of
// the GAS handleL2Batch coverage logic, as a deterministic CCR script. The
// LLM owns the prose; this script owns "which uncovered L1 source do we cover
// next", so the selection can't drift from the GAS rule.
//
// It queries the L1 source DB and the unified Articles DB (Type=explanation)
// using the injected Notion integration token, then returns an L1 source whose
// Source URL is not yet covered by an explanation. Same filters as
// handleL2Batch: skip example.com fixtures, skip rows with `L2 Skip`=true,
// oldest-first by created_time.
//
// A pick is only returned if its source body could actually be fetched
// ---------------------------------------------------------------------
// The previous version returned `pending[0]` unconditionally. When the oldest
// uncovered row was a bot-walled URL (reuters.com — HTTP 401 direct, and the
// reader fallback 403), the skill's hard rule "if you cannot quote the source,
// do not publish" meant the fire produced nothing — and because nothing was
// written back, the *next* fire picked the very same row. One unfetchable row
// stalled the entire queue indefinitely: every L1 source registered behind it
// waited forever. Combined with the fact that no failure was recorded
// anywhere, this was invisible.
//
// So this script now walks the queue instead of peeking at its head:
//
//   for each uncovered row, oldest first (up to MAX_CANDIDATES):
//     fetch the body (scripts/lib/source-fetch.mjs: direct → reader)
//     groundable? → return it, with the body already on disk
//     not groundable? → record the failure on the L1 row, try the next row
//
// A row that fails MAX_ATTEMPTS times is treated as blocked and drops out of
// the queue, so a permanently dead URL costs a bounded number of retries
// instead of blocking every successor forever. Nothing is ever silently
// dropped: the attempt count, the last error and its timestamp are written
// back to the L1 row (C-4), and the blocked count is reported on stderr.
//
// The CCR session never reads Secrets Manager: NOTION_API_KEY arrives inline
// from the task's `credentials["notion.integration_token"].apiKey` and is
// passed through as an env var by the runner. The DB ids are NOT secret (they
// are already committed in newsletter/pipeline/normalize-categories.mjs), so
// they live as constants below — overridable by env for tests / migrations.
//
// Usage:
//   NOTION_API_KEY="<credentials['notion.integration_token'].apiKey>" \
//     node workforce/skills/article-level2/pick-l1-source.mjs
//
// Stdout (single JSON line):
//   { "l1PageId", "title", "summary", "sourceUrl", "category",
//     "bodyFile", "bodyChars", "fetchedVia" }   ← cover this one; the source
//                                                 text is at bodyFile
//   { "skip": true, "reason": "..." }           ← nothing coverable this fire
//
// Contract note — the body is handed over on the FILESYSTEM
// ---------------------------------------------------------
// `bodyFile` points at a file in os.tmpdir(). That assumes the picker and the
// prompt that consumes it run in the same container, which is true of the
// agent-runner today and is written down here because it is exactly the kind
// of assumption that survives unnoticed until the runner topology changes.
// If they are ever split, the body has to travel in the payload instead.
//
// Exit codes:
//   0  — printed a pick OR a {skip:true} (both are valid outcomes)
//   1  — bad env
//   3  — Notion API / network error

import { ensureProxyAwareEntry } from "../../../scripts/lib/proxy-bootstrap.mjs";
ensureProxyAwareEntry(import.meta.url);

import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

import { fetchSourceBody } from "../../../scripts/lib/source-fetch.mjs";

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";

// Non-secret DB ids (mirror the unified Articles DB in
// newsletter/pipeline/normalize-categories.mjs). Env overrides allow test/migration.
const L1_DB_ID = process.env.L1_DB_ID || "32fd0f0b-e61e-80bd-89bf-f94965d05e80";
const UNIFIED_DB_ID = process.env.UNIFIED_DB_ID || "34fd0f0b-e61e-817a-9f6b-dc65b0d5b4cc";

/** Env override that fails loud instead of poisoning every comparison: a
 *  typo'd L2_MAX_ATTEMPTS would otherwise yield NaN, make every `<` false,
 *  and silently reduce the walk to `pending.slice(0, NaN)` === []. */
function intEnv(name, fallback) {
  const raw = process.env[name];
  if (raw === undefined || raw === "") return fallback;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 1) {
    console.error(`pick-l1-source.mjs: ${name} must be a positive integer (got "${raw}")`);
    process.exit(1);
  }
  return Math.floor(n);
}

// How many rows we are willing to try fetching in one fire. Bounds the
// runtime of a fire when the head of the queue is a run of dead URLs.
const MAX_CANDIDATES = intEnv("L2_MAX_CANDIDATES", 6);
// After this many failed fetches a row is considered blocked and leaves the
// queue. Deliberately > 1: readers throttle, and hosts have bad days.
const MAX_ATTEMPTS = intEnv("L2_MAX_ATTEMPTS", 5);
// Hard wall-clock budget for the candidate walk. Worst case per candidate is
// ~192s (45s direct + 3 reader legs at 45s + 12s backoff); six of those would
// be ~19 minutes of a CCR session spent to return {skip:true}. The walk stops
// at the budget and reports how many rows it never reached, rather than
// running until the session is killed mid-walk.
const WALK_BUDGET_MS = intEnv("L2_WALK_BUDGET_MS", 300_000);

// Operational columns this script maintains on the L1 rows. Created on demand
// (see ensureAttemptSchema) so no manual Notion migration is required.
const P_ATTEMPTS = "L2 Attempts";
const P_LAST_ERROR = "L2 Last Error";
const P_LAST_ATTEMPT = "L2 Last Attempt";

const apiKey = process.env.NOTION_API_KEY;

if (!apiKey) {
  console.error(
    "pick-l1-source.mjs: NOTION_API_KEY is required (credentials['notion.integration_token'].apiKey)",
  );
  process.exit(1);
}

const headers = {
  authorization: `Bearer ${apiKey}`,
  "notion-version": NOTION_VERSION,
  "content-type": "application/json",
};

async function queryAll(databaseId) {
  const pages = [];
  let cursor;
  do {
    const res = await fetch(`${NOTION_API}/databases/${databaseId}/query`, {
      method: "POST",
      headers,
      body: JSON.stringify(cursor ? { start_cursor: cursor, page_size: 100 } : { page_size: 100 }),
    });
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      throw new Error(`query ${databaseId} → HTTP ${res.status}: ${body.slice(0, 300)}`);
    }
    const data = await res.json();
    pages.push(...(data.results ?? []));
    cursor = data.has_more ? data.next_cursor : undefined;
  } while (cursor);
  return pages;
}

// Mirror of handleL2Batch's covered-URL set: unified rows with
// Type=explanation, source URL from `SourceURLs` (rich_text) or legacy
// `Source URLs` (url).
function coveredUrls(unifiedPages) {
  const set = new Set();
  for (const p of unifiedPages) {
    const type = p.properties?.Type?.select?.name ?? "";
    if (type !== "explanation") continue;
    const u =
      p.properties?.SourceURLs?.rich_text?.[0]?.plain_text ||
      p.properties?.["Source URLs"]?.url ||
      "";
    if (u) set.add(u.trim());
  }
  return set;
}

const attemptsOf = (page) => page.properties?.[P_ATTEMPTS]?.number ?? 0;

/** Add the operational columns to the L1 DB if they are missing. Called once,
 *  lazily, the first time we need to record a failure — so a fresh database
 *  (or a restored backup) self-heals instead of erroring out. */
let schemaEnsured = false;
async function ensureAttemptSchema() {
  if (schemaEnsured) return;
  const res = await fetch(`${NOTION_API}/databases/${L1_DB_ID}`, { headers });
  if (!res.ok) throw new Error(`read database → HTTP ${res.status}`);
  const db = await res.json();
  const missing = {};
  if (!db.properties?.[P_ATTEMPTS]) missing[P_ATTEMPTS] = { number: {} };
  if (!db.properties?.[P_LAST_ERROR]) missing[P_LAST_ERROR] = { rich_text: {} };
  if (!db.properties?.[P_LAST_ATTEMPT]) missing[P_LAST_ATTEMPT] = { date: {} };
  if (Object.keys(missing).length > 0) {
    const patch = await fetch(`${NOTION_API}/databases/${L1_DB_ID}`, {
      method: "PATCH",
      headers,
      body: JSON.stringify({ properties: missing }),
    });
    if (!patch.ok) {
      const body = await patch.text().catch(() => "");
      throw new Error(`add L2-attempt columns → HTTP ${patch.status}: ${body.slice(0, 200)}`);
    }
    console.error(`pick-l1-source.mjs: added L1 columns ${Object.keys(missing).join(", ")}`);
  }
  schemaEnsured = true;
}

// Set when a bookkeeping write fails. If attempts can't be persisted, the
// eviction budget never advances and a run of dead heads re-stalls the queue —
// the exact ML-018 failure, bounded to MAX_CANDIDATES rows instead of one.
// That must not be visible only on a stderr nobody reads (C-4), so it is
// surfaced in the machine-readable {skip:true} reason.
let bookkeepingBroken = null;

/** Record a failed fetch on the L1 row. Best-effort: a bookkeeping failure
 *  must not abort the fire, but it is always reported on stderr and in the
 *  outcome payload. */
async function recordFailure(page, reason) {
  try {
    await ensureAttemptSchema();
    const next = attemptsOf(page) + 1;
    const res = await fetch(`${NOTION_API}/pages/${page.id}`, {
      method: "PATCH",
      headers,
      body: JSON.stringify({
        properties: {
          [P_ATTEMPTS]: { number: next },
          [P_LAST_ERROR]: { rich_text: [{ text: { content: reason.slice(0, 1900) } }] },
          [P_LAST_ATTEMPT]: { date: { start: new Date().toISOString() } },
        },
      }),
    });
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      console.error(
        `pick-l1-source.mjs: could not record attempt on ${page.id} → HTTP ${res.status}: ${body.slice(0, 200)}`,
      );
      return;
    }
    console.error(
      `pick-l1-source.mjs: attempt ${next}/${MAX_ATTEMPTS} failed for ${page.properties?.["Source URL"]?.url} — ${reason}` +
        (next >= MAX_ATTEMPTS ? " [now blocked; leaves the queue]" : ""),
    );
  } catch (err) {
    bookkeepingBroken = err instanceof Error ? err.message : String(err);
    console.error(
      `pick-l1-source.mjs: could not record attempt on ${page.id}: ${bookkeepingBroken}`,
    );
  }
}

try {
  const [l1Pages, unifiedPages] = await Promise.all([queryAll(L1_DB_ID), queryAll(UNIFIED_DB_ID)]);
  const covered = coveredUrls(unifiedPages);

  const uncovered = l1Pages
    .filter((p) => {
      const u = p.properties?.["Source URL"]?.url;
      if (!u || covered.has(u.trim())) return false;
      if (/^https?:\/\/(www\.)?example\.com(\/|$)/i.test(u)) return false; // test fixtures
      if (p.properties?.["L2 Skip"]?.checkbox === true) return false; // operator skip
      return true;
    })
    .sort((a, b) => (a.created_time ?? "").localeCompare(b.created_time ?? "")); // oldest-first

  const blocked = uncovered.filter((p) => attemptsOf(p) >= MAX_ATTEMPTS);
  const pending = uncovered.filter((p) => attemptsOf(p) < MAX_ATTEMPTS);

  if (blocked.length > 0) {
    console.error(
      `pick-l1-source.mjs: ${blocked.length} row(s) blocked after ${MAX_ATTEMPTS} failed fetches ` +
        `(clear "${P_ATTEMPTS}" in Notion to retry, or tick "L2 Skip" to retire):`,
    );
    for (const p of blocked) {
      console.error(
        `    ${p.properties?.["Source URL"]?.url} — ${p.properties?.[P_LAST_ERROR]?.rich_text?.[0]?.plain_text ?? "?"}`,
      );
    }
  }

  if (pending.length === 0) {
    console.log(
      JSON.stringify({
        skip: true,
        reason:
          blocked.length > 0
            ? `no coverable L1 sources (${blocked.length} blocked after ${MAX_ATTEMPTS} failed fetches)`
            : "no uncovered L1 sources",
      }),
    );
    process.exit(0);
  }

  const tried = [];
  const deadline = Date.now() + WALK_BUDGET_MS;
  const willTry = pending.slice(0, MAX_CANDIDATES);
  let untried = willTry.length;
  for (const page of willTry) {
    if (Date.now() > deadline) break;
    untried--;
    const sourceUrl = page.properties?.["Source URL"]?.url ?? "";
    const result = await fetchSourceBody(sourceUrl);

    if (!result.ok) {
      tried.push(`${sourceUrl} (${result.reason})`);
      // A verdict that is only about the reader being throttled says nothing
      // about the source, so it must not count toward eviction — otherwise a
      // bad hour permanently drops a perfectly good row. The queue still
      // advances either way, because we move to the next candidate regardless.
      if (result.transient) {
        console.error(
          `pick-l1-source.mjs: transient failure for ${sourceUrl} (not counted toward ${MAX_ATTEMPTS}) — ${result.reason}`,
        );
      } else {
        await recordFailure(page, result.reason);
      }
      continue;
    }

    const bodyFile = join(tmpdir(), `l2-source-${page.id.replace(/-/g, "")}.md`);
    writeFileSync(bodyFile, result.text);

    console.log(
      JSON.stringify({
        l1PageId: page.id,
        title: page.properties?.Title?.title?.[0]?.plain_text ?? "",
        summary: page.properties?.["Contents Summary"]?.rich_text?.[0]?.plain_text ?? "",
        sourceUrl,
        category: page.properties?.Category?.rich_text?.[0]?.plain_text ?? "",
        bodyFile,
        bodyChars: result.chars,
        fetchedVia: result.via,
      }),
    );
    process.exit(0);
  }

  // Every candidate we were willing to try this fire failed to fetch. Their
  // attempt counters have been incremented, so a later fire reaches further
  // down the queue instead of retrying the same head forever.
  console.error(
    `pick-l1-source.mjs: none of the ${tried.length} candidate(s) tried this fire yielded a groundable body:`,
  );
  for (const t of tried) console.error(`    ${t}`);
  if (untried > 0) {
    console.error(
      `pick-l1-source.mjs: walk budget (${WALK_BUDGET_MS}ms) exhausted with ${untried} candidate(s) untried`,
    );
  }
  console.log(
    JSON.stringify({
      skip: true,
      reason:
        `no groundable source among the ${tried.length} oldest uncovered row(s); ` +
        `${pending.length} pending, ${blocked.length} blocked` +
        (untried > 0 ? `, ${untried} untried (walk budget exhausted)` : "") +
        (bookkeepingBroken ? `; ATTEMPTS NOT PERSISTED (${bookkeepingBroken}) — queue will re-stall` : ""),
    }),
  );
  process.exit(0);
} catch (err) {
  console.error(`pick-l1-source.mjs: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// Deterministic L2-explanation writer — invoked by the CCR agent-runner
// after it has *generated* the briefing-document markdown. The LLM owns the
// judgment (the prose); this script owns the structurally-exact Notion write
// so the failure class "LLM hand-edits the page JSON and guesses the schema
// wrong" cannot recur. Same shape as feed-post/post-feed.mjs.
//
// It POSTs a new page into the unified Articles DB using the injected Notion
// integration token. The row carries Author + Type=explanation +
// Status=ready (queued; the GAS L4 batch flips it to published) so it lands on
// kohuehara.xyz and newsletter/pipeline/fetch-notion.mjs surfaces the byline (AuthorChip).
//
// The CCR session never reads Secrets Manager: NOTION_API_KEY arrives inline
// from the task's `credentials["notion.integration_token"].apiKey` and is
// passed through as an env var by the runner. The target DB id is NOT secret
// (the unified Articles DB id is already committed in
// newsletter/pipeline/normalize-categories.mjs), so it's a constant below — overridable by
// NOTION_DB_ID for tests / migrations.
//
// W-1 (editorial integrity): the script refuses an empty / too-short body,
// rejects LLM-failure prelude artefacts, and rejects a body whose last line
// looks cut off mid-content (C-1), failing loud (exit 2) rather than landing
// a degraded article. The cut-off check is the canonical heuristic from
// scripts/lib/truncation.mjs — with the GAS cron paused this skill is the
// generation path, so the R-5-equivalent guard must fire here, per-article,
// rather than only at the R-10 deploy gate where one bad body blocks the
// whole site deploy.
//
// Body is read from a FILE (not an arg) so multi-line / Unicode prose can't be
// mangled by shell quoting. The first `# ` line is used as the page Title and
// stripped from the body blocks (so the rendered article doesn't repeat it).
//
// BILINGUAL (ADR-0005): every article is published in BOTH languages. The
// Japanese body writes the row; the English body writes an `EN` child page
// under it, which newsletter/pipeline/fetch-notion.mjs exports as
// `<slug>.en.md`. `--body-en-file` is therefore REQUIRED, not optional — the
// site's promise is that every article has both editions, so a fire that
// produced only Japanese is a failed fire and must say so (C-4) rather than
// quietly adding a row that the English reader will only ever see as a
// fallback. Both bodies clear the same W-1 guards, and all guards run BEFORE
// any write, so a bad English body publishes nothing at all.
//
// Usage:
//   NOTION_API_KEY="<credentials['notion.integration_token'].apiKey>" \
//     node workforce/skills/article-level2/publish-notion.mjs \
//       --author elena --type explanation --status ready \
//       --body-file /tmp/article.md \
//       --body-en-file /tmp/article.en.md \
//       [--source-url https://...] \
//       [--tags "AI Productivity,Org Transformation"]  # 3–5 flat tags from scripts/lib/tags.mjs
//       [--abstract-file /tmp/abstract.txt]  # L2 lead → Abstract
//       [--abstract-en-file /tmp/abstract.en.txt]  # English lead → EN page
//
// Exit codes:
//   0  — page created, in both editions
//   1  — bad args / env / body-file unreadable / no H1 title
//   2  — W-1 editorial guard failed (empty/short body, LLM-artefact prelude,
//        or cut-off last line) in EITHER edition
//   3  — Notion API error / network error; nothing was created
//   4  — the row was created but its English edition could not be written.
//        The article exists and is Japanese-only. Report the page URL on
//        stderr; the operator (or a re-run of backfill-en.mjs) completes it.

import { ensureProxyAwareEntry } from "../../../scripts/lib/proxy-bootstrap.mjs";
ensureProxyAwareEntry(import.meta.url);

import { readFileSync } from "node:fs";
import { isTruncatedMarkdown, lastNonEmptyLine } from "../../../scripts/lib/truncation.mjs";
import { validateTags } from "../../../scripts/lib/tags.mjs";
import {
  chunkBlocks,
  markdownToBlocks,
  writeEnChildPage,
} from "../../../scripts/lib/notion-i18n.mjs";

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";
// Non-secret target DB id (the unified Articles DB; mirror of the default in
// newsletter/pipeline/normalize-categories.mjs). Overridable by NOTION_DB_ID for tests.
const UNIFIED_DB_ID = process.env.NOTION_DB_ID || "34fd0f0b-e61e-817a-9f6b-dc65b0d5b4cc";
// An L2 explanation is ~3000 字; anything shorter than this floor is almost
// certainly a truncated / empty generation and must not be published (C-1).
const MIN_BODY_CHARS = 200;
// LLM-failure preludes — rejected in the first 50 chars (mirror of the
// feed-post POST /feed server-side guard).
const ARTEFACT_PRELUDE =
  /^\s*(as an ai|here is|here's|i apologize|i'm sorry|certainly!|sure,|of course)/i;

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

// Tags — flat vocabulary (ADR-0003). The retired A–E canonicalisation lived
// here; the single source of truth is now scripts/lib/tags.mjs. The agent
// picks 3–5 tags from that vocabulary (see SKILL.md) and passes them via
// --tags; validateTags drops anything not in the controlled set (never
// invents). Splits on comma so the runner can pass one shell arg.
function parseTags(raw) {
  return validateTags((raw || "").split(",").map((t) => t.trim()).filter(Boolean));
}

const apiKey = process.env.NOTION_API_KEY;
const databaseId = UNIFIED_DB_ID;
const author = arg("author");
const articleType = arg("type") ?? "explanation";
const status = arg("status") ?? "ready";
const bodyFile = arg("body-file");
const bodyEnFile = arg("body-en-file");       // REQUIRED — the English edition (ADR-0005)
const sourceUrl = arg("source-url");
const tagsArg = arg("tags");                  // comma-separated vocabulary tags (3–5)
const abstractFile = arg("abstract-file");    // optional lead/summary file
const abstractEnFile = arg("abstract-en-file"); // optional English lead

// Valid Status options on the unified Articles DB (mirror of the live select).
// L2 explanations land as `ready` (queued, not yet live); the GAS L4 batch
// flips them to `published`. (--status lets a backfill override.)
const VALID_STATUS = new Set(["draft", "ready", "published", "archived"]);

if (!apiKey) { console.error("publish-notion.mjs: NOTION_API_KEY env var is required (from credentials['notion.integration_token'].apiKey)"); process.exit(1); }
if (!author) { console.error("publish-notion.mjs: --author <slug> is required"); process.exit(1); }
if (articleType !== "explanation" && articleType !== "analysis") {
  console.error(`publish-notion.mjs: --type must be explanation|analysis (got "${articleType}")`);
  process.exit(1);
}
if (!VALID_STATUS.has(status)) {
  console.error(`publish-notion.mjs: --status must be one of ${[...VALID_STATUS].join("|")} (got "${status}")`);
  process.exit(1);
}
if (!bodyFile) { console.error("publish-notion.mjs: --body-file <path> is required"); process.exit(1); }
if (!bodyEnFile) {
  console.error("publish-notion.mjs: --body-en-file <path> is required — every article publishes in both editions (ADR-0005)");
  process.exit(1);
}

function readOrExit(path, flag) {
  try {
    return readFileSync(path, "utf8");
  } catch (err) {
    console.error(`publish-notion.mjs: cannot read --${flag} "${path}": ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  }
}

const body = readOrExit(bodyFile, "body-file");
const bodyEn = readOrExit(bodyEnFile, "body-en-file");

// Optional abstract (the L2 lead / source summary → the Abstract column, same
// role as l1Summary in the GAS L2 write). Read from a file so multi-line /
// Unicode prose isn't mangled by shell quoting, exactly like --body-file.
const abstract = abstractFile ? readOrExit(abstractFile, "abstract-file").trim() : "";
const abstractEn = abstractEnFile ? readOrExit(abstractEnFile, "abstract-en-file").trim() : "";

// ── W-1 editorial guards (fail loud, do not publish) ───────────────────────
// Applied identically to both editions, and to BOTH before anything is
// written: a translated body that got cut off is exactly as unpublishable as a
// Japanese one (C-1), and failing after the row exists would leave the corpus
// in the half-published state the guard exists to prevent.
function assertPublishable(text, edition) {
  const t = text.trim();
  if (t.length < MIN_BODY_CHARS) {
    console.error(`publish-notion.mjs: ${edition} body is ${t.length} chars (< ${MIN_BODY_CHARS}) — refusing to publish a truncated/empty explanation (W-1)`);
    process.exit(2);
  }
  if (ARTEFACT_PRELUDE.test(t.slice(0, 50))) {
    console.error(`publish-notion.mjs: ${edition} body opens with an LLM-failure prelude — refusing to publish (W-1)`);
    process.exit(2);
  }
  if (isTruncatedMarkdown(t)) {
    console.error(`publish-notion.mjs: ${edition} body looks cut off mid-content (last line: "${lastNonEmptyLine(t)}") — refusing to publish a truncated explanation (W-1)`);
    process.exit(2);
  }
  return t;
}

// First `# ` line is the title; strip it from the body blocks.
function splitTitle(text, edition) {
  const lines = text.split(/\r?\n/);
  const h1Idx = lines.findIndex((l) => /^#\s+\S/.test(l));
  if (h1Idx === -1) {
    console.error(`publish-notion.mjs: ${edition} body has no \`# Title\` H1 on its own line — the L2 format requires one (exit 1)`);
    process.exit(1);
  }
  return {
    title: lines[h1Idx].replace(/^#\s+/, "").trim(),
    body: lines.slice(0, h1Idx).concat(lines.slice(h1Idx + 1)).join("\n"),
  };
}

const trimmed = assertPublishable(body, "Japanese");
const trimmedEn = assertPublishable(bodyEn, "English");
const { title, body: bodyWithoutTitle } = splitTitle(trimmed, "Japanese");
const { title: titleEn, body: bodyEnWithoutTitle } = splitTitle(trimmedEn, "English");

const blocks = markdownToBlocks(bodyWithoutTitle);
// Notion caps `children` at 100 per request. The rest is appended after the
// page exists — the old code silently sliced it off, which is a C-1 hole that
// only stayed hidden because a ~3000字 article usually lands under the cap.
const [children, ...overflow] = chunkBlocks(blocks);

// Property names mirror the live unified Articles DB exactly (same contract as
// the GAS L2 write in newsletter/gas/src/Code.gs): Title (title), Type/Status (select),
// Author/SourceURLs (rich_text), Date. There is no Name/Kind/SourceURL(url)
// column — writing those returns HTTP 400 validation_error.
const properties = {
  Title: { title: [{ text: { content: title.slice(0, 2000) } }] },
  Author: { rich_text: [{ text: { content: author } }] },
  Type: { select: { name: articleType } },
  Status: { select: { name: status } },
  Date: { date: { start: new Date().toISOString().slice(0, 10) } },
};
// Coverage (pick-l1-source.mjs) keys on SourceURLs rich_text, so the next fire
// sees this source as covered and won't re-pick it.
if (sourceUrl) properties.SourceURLs = { rich_text: [{ text: { content: sourceUrl } }] };

// Abstract — the L2 lead (mirror of l1Summary in the GAS L2 write). Optional;
// only set when an --abstract-file was supplied and non-empty.
if (abstract) properties.Abstract = { rich_text: [{ text: { content: abstract.slice(0, 2000) } }] };

// Tags — the flat vocabulary tags (ADR-0003), the many-to-many
// field that drives the reader sidebar/filter. Category (single) carries the
// primary tag for legacy single-category consumers. Tags outside the
// vocabulary are dropped by validateTags; if --tags was given but nothing
// validated, publish untagged rather than block (W-1 governs the body, not
// tags) — but say so loudly.
const tags = parseTags(tagsArg);
if (tagsArg && tags.length === 0) {
  console.warn(`publish-notion.mjs: --tags "${tagsArg}" had no valid vocabulary tags — publishing untagged (see scripts/lib/tags.mjs TAGS)`);
}
if (tags.length) {
  properties.Category = { rich_text: [{ text: { content: tags[0] } }] };
  properties.Tags = { multi_select: tags.map((name) => ({ name })) };
}

/**
 * One Notion request. Throws an Error carrying `.status` and `.body` on any
 * non-2xx so the caller can map HTTP status onto this script's exit codes —
 * and so `writeEnChildPage` can stay a pure, injectable helper.
 */
async function notionFetch(method, path, payload) {
  const res = await fetch(`${NOTION_API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${apiKey}`,
      "notion-version": NOTION_VERSION,
      "content-type": "application/json",
    },
    body: payload === undefined ? undefined : JSON.stringify(payload),
  });
  const text = await res.text().catch(() => "");
  if (!res.ok) {
    const err = new Error(`Notion ${method} ${path} → HTTP ${res.status}: ${text.slice(0, 400)}`);
    err.status = res.status;
    throw err;
  }
  try { return JSON.parse(text); } catch { return {}; }
}

let page;
try {
  page = await notionFetch("POST", "/pages", {
    parent: { database_id: databaseId },
    properties,
    children,
  });
  for (const chunk of overflow) {
    await notionFetch("PATCH", `/blocks/${page.id}/children`, { children: chunk });
  }
} catch (err) {
  if (err.status === 401 || err.status === 403) {
    console.error(`publish-notion.mjs: auth rejected (HTTP ${err.status}) — project credential bag misconfigured: ${err.message}`);
    process.exit(2);
  }
  console.error(`publish-notion.mjs: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

// English edition (ADR-0005) — an `EN` child page under the row we just
// created. Its body already cleared the same W-1 guards, so the only way this
// fails now is a Notion/network fault, which is exit 4: the article exists but
// is Japanese-only, and that is a different operator action from "nothing was
// published".
try {
  const en = await writeEnChildPage({
    parentPageId: page.id,
    en: { title: titleEn, abstract: abstractEn, body: bodyEnWithoutTitle },
    notionFetch,
  });
  console.log(
    `publish-notion.mjs: created — Author=${author} Type=${articleType} Status=${status} ` +
      `"${title}" ${page.url ?? ""} (+ EN edition "${titleEn}", ${en.blocks} blocks)`,
  );
  process.exit(0);
} catch (err) {
  console.error(
    `publish-notion.mjs: the row was created but its English edition failed to write: ` +
      `${err instanceof Error ? err.message : String(err)}`,
  );
  console.error(`  Japanese article is live at ${page.url ?? page.id}. Complete it with:`);
  console.error(`  node newsletter/pipeline/backfill-en.mjs --page-id ${page.id}`);
  process.exit(4);
}

