// @ts-nocheck — the module under test (escalation-reasons.mjs) is a
// dependency-free ESM script, not TS; vitest/esbuild imports it fine at
// runtime, and this suite is not shipped code. Discovered by
// workforce/lambdas/vitest.config.mjs (`include: ["../skills/**/*-tests.ts"]`),
// so `cd workforce/lambdas && npm test` runs it.
//
// Locks the Epic-019 Story 1 taxonomy (workforce/docs/pr-escalation-reasons.md
// v1): the code list is closed (unknown code = throw, C-4), the sweep's three
// kind strings are reused verbatim, `other` never travels without free text,
// and every pr-merge.mjs refusal `why` string maps onto its taxonomy code.
import { describe, it, expect } from "vitest";
import {
  REASON_CODES,
  REASON_LABEL_PREFIX,
  assertReasonCode,
  reasonLabel,
  reasonMarker,
  findReasonMarkers,
  refusalReasonCode,
} from "./escalation-reasons.mjs";

describe("REASON_CODES (taxonomy v1)", () => {
  it("reuses the sweep's three kind strings verbatim (never flattened)", () => {
    for (const kind of ["unlabelled-handoff", "stale-routed", "never-routed"]) {
      expect(REASON_CODES).toContain(kind);
    }
  });
  it("carries every v1 code from the Epic-019 Story 1 list", () => {
    for (const code of [
      "l0l1-path", "human-changes-requested", "checks-failing", "checks-pending-aged",
      "no-reviewer-consensus", "not-mergeable", "kill-switch-off", "no-r-n10-delegation",
      "cannot-seat-panel", "persona-escalation-trigger", "cycle-cap-exceeded",
      "merge-engine-refusal", "other",
    ]) {
      expect(REASON_CODES).toContain(code);
    }
  });
});

describe("assertReasonCode / reasonLabel — unknown codes fail loud (C-4)", () => {
  it("accepts a taxonomy code", () => expect(assertReasonCode("l0l1-path")).toBe("l0l1-path"));
  it("throws on an unknown code, never invents a bucket", () => {
    expect(() => assertReasonCode("reviewer-was-slow")).toThrow(/unknown escalation-reason code/);
    expect(() => reasonLabel("reviewer-was-slow")).toThrow(/unknown escalation-reason code/);
  });
  it("builds the canonical label", () =>
    expect(reasonLabel("stale-routed")).toBe(`${REASON_LABEL_PREFIX}stale-routed`));
});

describe("reasonMarker — the hidden-comment carrier", () => {
  it("emits the bare marker for a specific code", () =>
    expect(reasonMarker("never-routed")).toBe("<!-- autopilot:reason:never-routed -->"));
  it("carries free text when given", () =>
    expect(reasonMarker("other", "target repo archived")).toBe("<!-- autopilot:reason:other target repo archived -->"));
  it("throws on `other` without free text — mislabeling cannot satisfy coverage", () => {
    expect(() => reasonMarker("other")).toThrow(/requires free text/);
    expect(() => reasonMarker("other", "   ")).toThrow(/requires free text/);
  });
  it("throws on an unknown code", () => expect(() => reasonMarker("nope")).toThrow(/unknown/));
  it("neutralises a comment-closing --> inside the free text", () =>
    expect(reasonMarker("other", "weird --> text")).not.toMatch(/--> text/));
});

describe("findReasonMarkers — parsing what emitters wrote", () => {
  it("finds code + text", () => {
    const body = `verdict…\n<!-- autopilot:needs-human -->\n<!-- autopilot:reason:cannot-seat-panel -->\n`;
    expect(findReasonMarkers(body)).toEqual([{ code: "cannot-seat-panel", text: "" }]);
  });
  it("returns the free text on an `other` marker", () => {
    expect(findReasonMarkers("<!-- autopilot:reason:other repo archived -->")).toEqual([
      { code: "other", text: "repo archived" },
    ]);
  });
  it("ignores the other autopilot:* markers", () => {
    const body = "<!-- autopilot:needs-human -->\n<!-- autopilot:reviewed -->\n<!-- autopilot:review:dario:green -->";
    expect(findReasonMarkers(body)).toEqual([]);
  });
  it("throws on a marker carrying an unknown code (C-4)", () => {
    expect(() => findReasonMarkers("<!-- autopilot:reason:sloppy-review -->")).toThrow(/unknown/);
  });
  it("throws on a bare `other` marker", () => {
    expect(() => findReasonMarkers("<!-- autopilot:reason:other -->")).toThrow(/free text/);
  });
});

describe("refusalReasonCode — pr-merge.mjs `why` strings map 1:1 (verbatim phrasing)", () => {
  const CASES: Array<[string, string]> = [
    ["autopilot:off label set — paused by maintainer", "kill-switch-off"],
    ["cannot read target governance docs/governance.md (HTTP 404) — L0/L1 set unknown, failing merge closed", "no-r-n10-delegation"],
    ["docs/governance.md declares no <!-- autopilot:l0l1-paths --> block — L0/L1 set unknown, failing merge closed", "no-r-n10-delegation"],
    ["docs/governance.md L0/L1 block is empty — failing merge closed", "no-r-n10-delegation"],
    ["touches L0/L1 path docs/governance.md — escalate to human (operator's final call)", "l0l1-path"],
    ["a reviewer has CHANGES_REQUESTED — not consensus-green", "human-changes-requested"],
    ["check 'ci' is in_progress", "checks-pending-aged"],
    ["check 'ci' = failure", "checks-failing"],
    // adr-0022: the engine's single mergeability refusal splits by state —
    // dirty/behind name an agent-fixable branch condition (author lane),
    // every other state stays the human lane's `not-mergeable`.
    ["not mergeable (mergeable=false, state=dirty)", "merge-conflict"],
    ["not mergeable (mergeable=false, state=behind)", "branch-behind"],
    ["not mergeable (mergeable=false, state=blocked)", "not-mergeable"],
    ["not mergeable (mergeable=null, state=unknown)", "not-mergeable"],
    ["review reached cycle 8, exceeding the W-4 hard cap of 7 — process breakdown, escalate to human", "cycle-cap-exceeded"],
    ["missing green marker(s) from ren (expected <!-- autopilot:review:ren:green -->) — consensus not reached", "no-reviewer-consensus"],
    ["only 2 distinct reviewer(s) signed off — a merge requires a panel of at least 3 unanimous-green reviewers (operator directive 2026-06-29); under-reviewed merge refused", "no-reviewer-consensus"],
  ];
  for (const [why, code] of CASES) {
    it(`"${why.slice(0, 48)}…" → ${code}`, () => expect(refusalReasonCode(why)).toBe(code));
  }
  it("an unmatched refusal falls back to merge-engine-refusal, never a guess", () => {
    expect(refusalReasonCode("PR #7 is closed")).toBe("merge-engine-refusal");
    expect(refusalReasonCode("merge PUT rejected HTTP 405")).toBe("merge-engine-refusal");
    expect(refusalReasonCode("")).toBe("merge-engine-refusal");
  });
  it("every mapped code is inside the taxonomy (the map cannot drift)", () => {
    for (const [why] of CASES) expect(() => assertReasonCode(refusalReasonCode(why))).not.toThrow();
  });
});

#!/usr/bin/env node
// pr-autopilot/escalation-reasons.mjs — the versioned escalation-reason
// taxonomy (Epic-019 Story 1; prose twin: workforce/docs/pr-escalation-reasons.md).
//
// Every `autopilot:needs-human` hand-off records WHY it escalated, twice:
//   - an `autopilot:reason:<code>` label — the aggregation source
//     (build-pr-metrics-github.mjs buckets escalated PRs by this family into
//     the PERF#{scope}/PR roll-up), and
//   - a hidden comment marker `<!-- autopilot:reason:<code> -->` — the per-PR
//     audit trail, extending the existing `<!-- autopilot:… -->` convention
//     (`other` carries its MANDATORY free text inside the marker).
//
// These codes measure the autopilot's WIRING — which predicate clause or
// process leg forced the hand-off — never reviewer performance; they are
// inadmissible as Epic-023 "incidents" (Epic-019 RFC 2026-07-07).
//
// Dependency-free and pure so pr-merge.mjs / pr-autopilot-post.mjs /
// pr-autopilot-sweep.mjs all import it without cycles. Fail loud (C-4): an
// unknown code is a thrown Error, never a silently-invented bucket.

export const REASON_LABEL_PREFIX = "autopilot:reason:";

// Taxonomy v3.1 (2026-08-05; v3 2026-08-02; v2 2026-07-29). The terminal-state sweep's kind strings are
// reused VERBATIM as codes (never flattened); the merge-engine clauses map via
// refusalReasonCode() below. Adding/renaming a code = a version bump of the
// prose twin in the same PR.
//
// v2 (adr-0022) splits the hand-off into two lanes. A reason code now says
// which lane a PR was handed to as well as why:
//   - the HUMAN lane (`autopilot:needs-human`) — nothing an agent may do next;
//   - the AUTHOR lane (`autopilot:needs-author`) — an agent-fixable defect the
//     `pr-remediate` cadence owns (AUTHOR_LANE_CODES below).
// The funnel is unaffected: build-pr-metrics-github.mjs searches
// `label:autopilot:needs-human`, so an author-lane hand-off is never counted
// as an escalation — which is the point, it is not one.
export const REASON_CODES = Object.freeze([
  // pr-autopilot-sweep.mjs violation kinds — verbatim.
  "unlabelled-handoff",
  "stale-routed",
  "never-routed",
  // adr-0022: a PR parked in the author lane whose head never moved — the
  // remediation cadence failed to act, so the sweep escalates it to a human.
  "author-stale",
  // Merge-engine refusal clauses (pr-merge.mjs `why` strings) + the SKILL.md
  // verdict-table / session hand-off causes.
  "l0l1-path",
  "human-changes-requested",
  "checks-failing",
  "checks-pending-aged",
  "no-reviewer-consensus",
  "not-mergeable",
  "kill-switch-off",
  "no-r-n10-delegation",
  "cannot-seat-panel",
  "persona-escalation-trigger",
  "cycle-cap-exceeded",
  "merge-engine-refusal",
  // adr-0022 AUTHOR-lane causes: an agent-fixable defect, handed to the
  // author-side `pr-remediate` cadence rather than to a human.
  "merge-conflict",
  "branch-behind",
  "review-findings-open",
  // adr-0023: a 🔴 verdict whose blocking cause is diff-local — a reviewer veto
  // the router synthesised into an ordered remediation brief. Distinct from the
  // 🟡 `review-findings-open` above so the funnel can tell "author was asked to
  // revise" from "the panel blocked and the router organised the fix", and so
  // the brief requirement attaches to exactly this code (remediation-brief.mjs).
  "review-findings-blocking",
  // adr-0022 author-lane EXITS to the human lane: remediation was tried and
  // could not finish (bounded), or could not be tried safely.
  "remediation-cap-exceeded",
  "remediation-blocked",
  // Catch-all — REQUIRES free text (the codes we didn't anticipate are the
  // finding; a bare `other` would let the 100%-coverage criterion be met by
  // mislabeling).
  "other",
]);

const CODE_SET = new Set(REASON_CODES);

// adr-0022: the subset whose cause is AGENT-FIXABLE. A hand-off carrying one of
// these goes to the author lane (`autopilot:needs-author`, worked by the
// `pr-remediate` cadence), not to a human — the human lane is for decisions an
// agent may not make, and "main moved under this branch" is not one of them.
//
// Deliberately NOT in this set: `checks-failing`. A failing check can be an
// author-side defect OR a real product breakage, and the flaky-rerun latch
// (Story 2c) already owns the bounded retry — routing every red check into an
// automatic fix loop would launder a genuine failure into a patch attempt. The
// router may still hand a checks-failing PR to the author lane explicitly
// (SKILL.md Step 5) when the lens reviews located the defect in the diff; the
// default direction stays the loud one (C-4).
export const AUTHOR_LANE_CODES = Object.freeze([
  "merge-conflict",
  "branch-behind",
  "review-findings-open",
  // adr-0023 — the 🔴 loop. A reviewer veto is agent-fixable when the defect it
  // names is in the diff; what makes it safe to route here rather than to a
  // human is not the colour but the two bounds the post script enforces on this
  // code specifically: a machine-checked remediation brief, and the review
  // loop's own cycle budget (past the cap → `cycle-cap-exceeded`, a human).
  "review-findings-blocking",
]);
const AUTHOR_LANE_SET = new Set(AUTHOR_LANE_CODES);

/** True when `code` names an agent-fixable cause (the author lane). Throws on
 *  an unknown code — the same C-4 posture as every other reader here. */
export function isAuthorLaneCode(code) {
  return AUTHOR_LANE_SET.has(assertReasonCode(code));
}

/** C-4 gate: an unknown code throws, never becomes a quiet new bucket. */
export function assertReasonCode(code) {
  if (!CODE_SET.has(code)) {
    throw new Error(
      `unknown escalation-reason code "${code}" — must be one of: ${REASON_CODES.join(", ")} ` +
        `(taxonomy v3.1, workforce/docs/pr-escalation-reasons.md; C-4: never invent a bucket)`,
    );
  }
  return code;
}

/** The label carrier: `autopilot:reason:<code>`. Throws on an unknown code. */
export function reasonLabel(code) {
  return `${REASON_LABEL_PREFIX}${assertReasonCode(code)}`;
}

/** The hidden-marker carrier: `<!-- autopilot:reason:<code> [free text] -->`.
 *  Free text is optional for every code except `other`, where it is mandatory. */
export function reasonMarker(code, freeText = "") {
  assertReasonCode(code);
  // "--\x3e" inside the text would close the HTML comment early; neutralise it.
  const text = String(freeText || "").trim().replace(/-->/g, "→");
  if (code === "other" && !text) {
    throw new Error(`escalation reason "other" requires free text — the unanticipated cause IS the finding (taxonomy v3.1)`);
  }
  return text ? `<!-- autopilot:reason:${code} ${text} -->` : `<!-- autopilot:reason:${code} -->`;
}

const REASON_MARKER_RE = /<!--\s*autopilot:reason:([a-z0-9-]+)([^>]*?)\s*-->/g;

/** Parse every reason marker in a comment body → [{ code, text }]. Throws
 *  (C-4) on an unknown code or an `other` marker missing its free text. */
export function findReasonMarkers(body) {
  const found = [];
  const re = new RegExp(REASON_MARKER_RE.source, "g");
  let m;
  while ((m = re.exec(String(body ?? ""))) !== null) {
    const code = assertReasonCode(m[1].toLowerCase());
    const text = m[2].trim();
    if (code === "other" && !text) {
      throw new Error(`marker <!-- autopilot:reason:other --> is missing its mandatory free text (taxonomy v3.1)`);
    }
    found.push({ code, text });
  }
  return found;
}

// Map a pr-merge.mjs refusal `why` string onto its taxonomy code. Ordered:
// first match wins, specific clauses before generic ones. The patterns quote
// the engine's exact phrasing (verifyMergeable / resolveL0L1Paths); anything
// unmatched is `merge-engine-refusal`, the engine's own catch-all (closed PR,
// draft-flip failure, a rejected GitHub write) — never a guess at a clause.
const REFUSAL_WHY_MAP = [
  [/autopilot:off/i, "kill-switch-off"],
  // resolveL0L1Paths failures: the target's delegation block is unreadable /
  // absent / empty, i.e. no readable R-N10 delegation (fail-closed).
  [/cannot read target governance|declares no .* block|l0\/l1 block is empty/i, "no-r-n10-delegation"],
  [/touches l0\/l1 path/i, "l0l1-path"],
  [/changes_requested/i, "human-changes-requested"],
  [/check '.*' is /i, "checks-pending-aged"], // status ≠ completed at verdict time
  [/check '.*' = /i, "checks-failing"], // completed with a non-green conclusion
  // adr-0022: split the engine's single `not mergeable (mergeable=…, state=…)`
  // refusal by GitHub's mergeable_state, because two of its values name an
  // agent-fixable branch condition rather than a human decision:
  //   dirty  → the head conflicts with the base (main moved) → author lane
  //   behind → the head is out of date under a strict branch rule → author lane
  // Every other state (blocked / unstable / unknown) stays `not-mergeable`,
  // the human lane, unchanged. Ordered before the generic pattern.
  [/not mergeable.*state=dirty/i, "merge-conflict"],
  [/not mergeable.*state=behind/i, "branch-behind"],
  [/not mergeable/i, "not-mergeable"],
  [/w-4 hard cap/i, "cycle-cap-exceeded"],
  [/missing green marker|unanimous-green reviewers|distinct reviewer/i, "no-reviewer-consensus"],
];

export function refusalReasonCode(why) {
  const s = String(why || "");
  for (const [re, code] of REFUSAL_WHY_MAP) {
    if (re.test(s)) return code;
  }
  return "merge-engine-refusal";
}

// @ts-nocheck — the module under test (flaky-rerun.mjs) is a dependency-free
// ESM script, not TS; vitest/esbuild imports it fine at runtime, and this
// suite is not shipped code. Discovered by workforce/lambdas/vitest.config.mjs
// (`include: ["../skills/**/*-tests.ts"]`), so `cd workforce/lambdas && npm test`
// runs it.
//
// Locks Epic-019 Story 2c (Farah's rerun discipline): the allowlist is
// evidenced + expiring (no evergreen exemptions), editorial/deploy-class
// checks are categorically ineligible, max ONE rerun per PR (the hidden
// marker is the once-ever latch, posted BEFORE the rerun fires), a mixed
// failing set escalates, and ambiguous states throw or escalate — never a
// silent pass (C-4).
import { describe, it, expect } from "vitest";
import {
  MAX_RERUNS_PER_PR,
  RERAN_LABEL,
  RERUN_MARKER_PREFIX,
  EDITORIAL_INELIGIBLE_RE,
  validateFlakyChecks,
  activeAllowlist,
  hasRerunMarker,
  rerunMarker,
  findRerunMarkers,
  decideRerun,
  rerunAuditBody,
  attemptFlakyRerun,
} from "./flaky-rerun.mjs";

const TODAY = "2026-07-08";
const ENTRY = (check_name, over = {}) => ({
  check_name,
  evidence: "https://github.com/refluster/ai-native-article/issues/999",
  expires: "2026-12-31",
  ...over,
});

describe("validateFlakyChecks — evidenced + expiring allowlist (Farah's discipline)", () => {
  it("accepts an empty allowlist (ships empty; entries land with evidence as flakes occur)", () => {
    expect(validateFlakyChecks([], { today: TODAY })).toEqual({ errors: [], warnings: [] });
  });
  it("accepts a well-formed entry (URL evidence) and one with an issue-ref evidence", () => {
    const r = validateFlakyChecks(
      [ENTRY("integration-e2e"), ENTRY("lambda-smoke", { evidence: "#450" }), ENTRY("infra-drift", { evidence: "refluster/ai-native-article#450" })],
      { today: TODAY },
    );
    expect(r.errors).toEqual([]);
    expect(r.warnings).toEqual([]);
  });
  it("rejects an entry without evidence — no evidence, no entry", () => {
    const { errors } = validateFlakyChecks([{ check_name: "integration-e2e", expires: "2026-12-31" }], { today: TODAY });
    expect(errors.join("\n")).toMatch(/evidence/);
  });
  it("rejects non-URL / non-issue-ref evidence", () => {
    const { errors } = validateFlakyChecks([ENTRY("integration-e2e", { evidence: "trust me" })], { today: TODAY });
    expect(errors.join("\n")).toMatch(/evidence/);
  });
  it("rejects an entry without expires — no evergreen exemptions", () => {
    const { errors } = validateFlakyChecks([{ check_name: "integration-e2e", evidence: "#450" }], { today: TODAY });
    expect(errors.join("\n")).toMatch(/expires/);
  });
  it("rejects a malformed expires date", () => {
    const { errors } = validateFlakyChecks([ENTRY("integration-e2e", { expires: "soonish" })], { today: TODAY });
    expect(errors.join("\n")).toMatch(/YYYY-MM-DD/);
  });
  it("WARNS (not errors) on an expired entry — inert at runtime, prune it", () => {
    const { errors, warnings } = validateFlakyChecks([ENTRY("integration-e2e", { expires: "2026-07-01" })], { today: TODAY });
    expect(errors).toEqual([]);
    expect(warnings.join("\n")).toMatch(/expired 2026-07-01/);
  });
  it("HARD-errors on editorial/deploy-class check names (R-10/W-1: categorically ineligible)", () => {
    for (const name of ["deploy-article-site", "article-health", "corpus-truncation-gate", "Editorial Guard", "Deploy to gh-pages"]) {
      const { errors } = validateFlakyChecks([ENTRY(name)], { today: TODAY });
      expect(errors.join("\n")).toMatch(/rerun-ineligible/);
    }
  });
  it("rejects duplicates, unknown keys, non-object entries, and a non-array file", () => {
    expect(validateFlakyChecks([ENTRY("e2e"), ENTRY("E2E")], { today: TODAY }).errors.join("\n")).toMatch(/duplicate/);
    expect(validateFlakyChecks([ENTRY("e2e", { note: "x" })], { today: TODAY }).errors.join("\n")).toMatch(/unknown key/);
    expect(validateFlakyChecks(["e2e"], { today: TODAY }).errors.join("\n")).toMatch(/must be an object/);
    expect(validateFlakyChecks({ checks: [] }, { today: TODAY }).errors.join("\n")).toMatch(/must be a JSON array/);
  });
});

describe("activeAllowlist — unexpired entries only; malformed lists throw (C-4)", () => {
  it("drops expired entries and keys by lowercased name", () => {
    const m = activeAllowlist([ENTRY("E2E-Suite"), ENTRY("old-check", { expires: "2026-01-01" })], TODAY);
    expect(m.has("e2e-suite")).toBe(true);
    expect(m.has("old-check")).toBe(false);
  });
  it("throws on a malformed allowlist — a broken file never authorises a rerun", () => {
    expect(() => activeAllowlist([{ check_name: "e2e" }], TODAY)).toThrow(/invalid/);
    expect(() => activeAllowlist([ENTRY("deploy-site")], TODAY)).toThrow(/rerun-ineligible/);
  });
});

describe("rerun marker — the once-ever latch + machine-readable check names", () => {
  it("round-trips check names through the marker", () => {
    const marker = rerunMarker(["integration-e2e", "lambda smoke"]);
    expect(marker.startsWith(RERUN_MARKER_PREFIX)).toBe(true);
    expect(findRerunMarkers(marker)).toEqual([{ checks: ["integration-e2e", "lambda smoke"] }]);
  });
  it("neutralises --> and | inside check names", () => {
    const marker = rerunMarker(["weird --> name", "a|b"]);
    expect(marker.match(/-->/g)).toHaveLength(1); // only the closing token
    expect(findRerunMarkers(marker)[0].checks).toEqual(["weird → name", "a/b"]);
  });
  it("hasRerunMarker detects the latch anywhere in the bodies", () => {
    expect(hasRerunMarker(["routing…", `audit\n${rerunMarker(["e2e"])}`])).toBe(true);
    expect(hasRerunMarker(["routing…", "<!-- autopilot:needs-human -->"])).toBe(false);
    expect(hasRerunMarker([])).toBe(false);
  });
});

describe("decideRerun — the pure decision core", () => {
  const entries = [ENTRY("integration-e2e"), ENTRY("lambda-smoke")];

  it("all failing checks allowlisted + no prior rerun → rerun (with evidence carried)", () => {
    const d = decideRerun({ failingChecks: ["integration-e2e", "lambda-smoke"], entries, bodies: [], today: TODAY });
    expect(d.reran).toBe(true);
    expect(d.checks).toEqual(["integration-e2e", "lambda-smoke"]);
    expect(d.evidence[0]).toMatchObject({ check: "integration-e2e", expires: "2026-12-31" });
  });
  it("second time (marker present) → escalate checks-failing, never retried", () => {
    const bodies = [rerunAuditBody(decideRerun({ failingChecks: ["integration-e2e"], entries, bodies: [], today: TODAY }))];
    const d = decideRerun({ failingChecks: ["integration-e2e"], entries, bodies, today: TODAY });
    expect(d).toMatchObject({ reran: false, escalateWith: "checks-failing" });
    expect(d.why).toMatch(new RegExp(`max ${MAX_RERUNS_PER_PR}`));
  });
  it("a mixed failing set (one check not allowlisted) → escalate", () => {
    const d = decideRerun({ failingChecks: ["integration-e2e", "unit-tests"], entries, bodies: [], today: TODAY });
    expect(d).toMatchObject({ reran: false, escalateWith: "checks-failing" });
    expect(d.why).toMatch(/unit-tests/);
  });
  it("an expired allowlist entry no longer authorises its check", () => {
    const d = decideRerun({ failingChecks: ["e2e"], entries: [ENTRY("e2e", { expires: "2026-07-07" })], bodies: [], today: TODAY });
    expect(d).toMatchObject({ reran: false, escalateWith: "checks-failing" });
  });
  it("an editorial/deploy-class failing check escalates even before the allowlist is consulted", () => {
    const d = decideRerun({ failingChecks: ["deploy-article-site"], entries: [], bodies: [], today: TODAY });
    expect(d).toMatchObject({ reran: false, escalateWith: "checks-failing" });
    expect(d.why).toMatch(/categorically rerun-ineligible/);
    expect(EDITORIAL_INELIGIBLE_RE.test("deploy-article-site")).toBe(true);
  });
  it("throws on an empty or unnamed failing set — ambiguity never silently passes (C-4)", () => {
    expect(() => decideRerun({ failingChecks: [], entries, bodies: [], today: TODAY })).toThrow(/ambiguous/);
    expect(() => decideRerun({ failingChecks: [""], entries, bodies: [], today: TODAY })).toThrow(/ambiguous/);
    expect(() => decideRerun({ failingChecks: "e2e", entries, bodies: [], today: TODAY })).toThrow(/array/);
  });
  it("its escalate code is inside the taxonomy (cannot drift)", () => {
    const d = decideRerun({ failingChecks: ["nope"], entries, bodies: [], today: TODAY });
    expect(d.escalateWith).toBe("checks-failing");
  });
});

/** Route a `${method} ${path}` string to a canned {status,json} response
 *  (pr-merge-tests.ts style), recording calls for order assertions. */
function mockGh(routes) {
  const calls = [];
  const gh = async (method, path, body) => {
    calls.push({ method, path, body });
    for (const [re, resp] of routes) {
      if (re.test(`${method} ${path}`)) return typeof resp === "function" ? resp() : resp;
    }
    return { status: 404, json: {} };
  };
  gh.calls = calls;
  return gh;
}

const CHECK = (name, over = {}) => ({
  id: 11,
  name,
  status: "completed",
  conclusion: "failure",
  app: { slug: "github-actions" },
  ...over,
});

const ioRoutes = ({ checks, comments = [], workflowRuns, commentStatus = 201 }) => [
  [/GET \/repos\/o\/r\/pulls\/7$/, { status: 200, json: { head: { sha: "abc" } } }],
  [/GET \/repos\/o\/r\/commits\/abc\/check-runs/, { status: 200, json: { check_runs: checks } }],
  [/GET \/repos\/o\/r\/issues\/7\/comments/, { status: 200, json: comments }],
  [/GET \/repos\/o\/r\/pulls\/7\/reviews/, { status: 200, json: [] }],
  [/POST \/repos\/o\/r\/issues\/7\/comments/, { status: commentStatus, json: { id: 1 } }],
  [/POST \/repos\/o\/r\/labels/, { status: 201, json: {} }],
  [/POST \/repos\/o\/r\/issues\/7\/labels/, { status: 200, json: {} }],
  [/GET \/repos\/o\/r\/actions\/runs\?head_sha=abc/, { status: 200, json: { workflow_runs: workflowRuns } }],
  [/POST \/repos\/o\/r\/actions\/runs\/5\/rerun-failed-jobs/, { status: 201, json: {} }],
  [/POST \/repos\/o\/r\/check-runs\/11\/rerequest/, { status: 201, json: {} }],
];

const FAILED_RUN = { id: 5, status: "completed", conclusion: "failure" };
const entries = [ENTRY("integration-e2e")];

describe("attemptFlakyRerun — thin IO around the decision core", () => {
  it("happy path: all-allowlisted Actions failure → audit comment, reran label, rerun-failed-jobs", async () => {
    const gh = mockGh(ioRoutes({ checks: [CHECK("integration-e2e")], workflowRuns: [FAILED_RUN, { id: 6, status: "completed", conclusion: "success" }] }));
    const r = await attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY });
    expect(r).toMatchObject({ reran: true, checks: ["integration-e2e"], triggered: 1 });
    const posts = gh.calls.filter((c) => c.method === "POST").map((c) => c.path);
    expect(posts).toContain("/repos/o/r/actions/runs/5/rerun-failed-jobs");
    expect(posts).toContain("/repos/o/r/issues/7/labels");
    // The once-ever latch (audit marker comment) lands BEFORE the rerun fires.
    expect(posts.indexOf("/repos/o/r/issues/7/comments")).toBeLessThan(posts.indexOf("/repos/o/r/actions/runs/5/rerun-failed-jobs"));
    const audit = gh.calls.find((c) => c.method === "POST" && c.path === "/repos/o/r/issues/7/comments").body.body;
    expect(audit).toContain(RERUN_MARKER_PREFIX);
    expect(audit).toContain("integration-e2e");
    expect(audit).toContain(entries[0].evidence);
    expect(gh.calls.find((c) => c.path === "/repos/o/r/issues/7/labels").body.labels).toEqual([RERAN_LABEL]);
  });
  it("a non-Actions failing check is rerequested by check-run id", async () => {
    const gh = mockGh(ioRoutes({ checks: [CHECK("integration-e2e", { app: { slug: "some-ci-app" } })], workflowRuns: [] }));
    const r = await attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY });
    expect(r).toMatchObject({ reran: true, triggered: 1 });
    expect(gh.calls.some((c) => c.method === "POST" && c.path === "/repos/o/r/check-runs/11/rerequest")).toBe(true);
  });
  it("the marker in an existing comment blocks a second rerun (escalate, nothing posted)", async () => {
    const gh = mockGh(ioRoutes({ checks: [CHECK("integration-e2e")], comments: [{ body: rerunMarker(["integration-e2e"]) }], workflowRuns: [FAILED_RUN] }));
    const r = await attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY });
    expect(r).toMatchObject({ reran: false, escalateWith: "checks-failing" });
    expect(gh.calls.some((c) => c.method === "POST")).toBe(false);
  });
  it("an empty allowlist short-circuits to escalate with zero API calls", async () => {
    const gh = mockGh([]);
    const r = await attemptFlakyRerun(gh, "o/r", 7, { entries: [], today: TODAY });
    expect(r).toMatchObject({ reran: false, escalateWith: "checks-failing" });
    expect(gh.calls).toHaveLength(0);
  });
  it("a still-pending check is ambiguous → escalate, no rerun (C-4)", async () => {
    const gh = mockGh(ioRoutes({ checks: [CHECK("integration-e2e"), CHECK("slow-suite", { status: "in_progress", conclusion: null })], workflowRuns: [FAILED_RUN] }));
    const r = await attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY });
    expect(r).toMatchObject({ reran: false, escalateWith: "checks-failing" });
    expect(r.why).toMatch(/not completed/);
  });
  it("no failing checks at rerun time → escalate (re-verdict), never a guess", async () => {
    const gh = mockGh(ioRoutes({ checks: [CHECK("integration-e2e", { conclusion: "success" })], workflowRuns: [] }));
    const r = await attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY });
    expect(r).toMatchObject({ reran: false, escalateWith: "checks-failing" });
  });
  it("a failed audit comment aborts BEFORE any rerun fires (the latch must exist first)", async () => {
    const gh = mockGh(ioRoutes({ checks: [CHECK("integration-e2e")], workflowRuns: [FAILED_RUN], commentStatus: 500 }));
    await expect(attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY })).rejects.toThrow(/max-1 latch/);
    expect(gh.calls.some((c) => c.path.includes("rerun-failed-jobs"))).toBe(false);
  });
  it("a rejected rerun POST throws — a half-triggered rerun escalates, never silently passes (C-4)", async () => {
    const routes = ioRoutes({ checks: [CHECK("integration-e2e")], workflowRuns: [FAILED_RUN] }).filter(
      ([re]) => !re.test("POST /repos/o/r/actions/runs/5/rerun-failed-jobs"),
    );
    routes.push([/POST \/repos\/o\/r\/actions\/runs\/5\/rerun-failed-jobs/, { status: 403, json: {} }]);
    const gh = mockGh(routes);
    await expect(attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY })).rejects.toThrow(/HTTP 403/);
  });
  it("deciding to rerun but finding nothing to trigger throws (ambiguous)", async () => {
    const gh = mockGh(ioRoutes({ checks: [CHECK("integration-e2e")], workflowRuns: [{ id: 6, status: "completed", conclusion: "success" }] }));
    await expect(attemptFlakyRerun(gh, "o/r", 7, { entries, today: TODAY })).rejects.toThrow(/nothing to trigger/);
  });
});

#!/usr/bin/env node
// pr-autopilot/flaky-rerun.mjs — Epic-019 Story 2c: BOUNDED auto-rerun of
// known-flaky checks, under Farah's discipline (Epic-019 RFC 2026-07-07 Q2):
//
//   - The flake allowlist is a reviewed repo file (flaky-checks.json, sibling
//     of this module): an array of { check_name, evidence, expires }. EVERY
//     entry cites flake evidence (a URL or an issue ref) and carries an
//     expiry date — no evergreen exemptions. validate-skills.mjs (the
//     `workforce:skills` CI gate) rejects entries missing either, and warns
//     on expired ones; an expired entry never reruns at runtime either.
//   - R-10 / W-1-class editorial/deploy gates are CATEGORICALLY ineligible:
//     any check name matching EDITORIAL_INELIGIBLE_RE is a hard validation
//     error in the allowlist and an unconditional escalate at decision time,
//     even if an entry somehow slipped in (defence in depth).
//   - Max ONE rerun per PR, ever. The once-ever latch is the hidden audit
//     marker `<!-- autopilot:rerun:… -->` posted on the PR BEFORE any rerun
//     is triggered — so a crash mid-flight can forfeit the rerun, never
//     double it. A rerun-then-pass stays visible via that comment + the
//     `autopilot:reran` label (never a silent green); a rerun that still
//     fails escalates as `checks-failing`, never retried.
//   - C-4: unknown/ambiguous states (pending checks, an unreadable
//     allowlist, a rerun trigger that half-fails) THROW or return an
//     escalate decision — they never silently pass. Escalating is the safe
//     direction; the rerun is only ever an optimisation on top of it.
//
// Callers: pr-autopilot-post.mjs invokes attemptFlakyRerun() when a verdict
// is about to escalate with reason `checks-failing` — the rerun attempt
// happens BEFORE the escalation is posted, and only the all-allowlisted case
// defers it. This module deliberately does NOT touch pr-merge.mjs /
// verifyMergeable: the R-N10 predicate's decision flow stays byte-identical
// (a rerun just gives the checks a second chance to be genuinely green by
// the next verdict).
//
// Pure decision core (decideRerun, validateFlakyChecks, marker helpers) +
// a thin IO wrapper (attemptFlakyRerun) in the pr-merge.mjs makeGh style.

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { assertReasonCode } from "./escalation-reasons.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));

/** The reviewed, evidenced, expiring flake allowlist (ships EMPTY — entries
 *  are added with evidence as real flakes occur, never pre-emptively). */
export const FLAKY_CHECKS_PATH = join(HERE, "flaky-checks.json");

/** Hard bound: one rerun per PR, ever (Farah's discipline). */
export const MAX_RERUNS_PER_PR = 1;

/** Label stamped on a PR whose checks were rerun — the metrics signal
 *  build-pr-metrics-github.mjs counts (rerun / rerun-then-pass per check),
 *  so a racy check is detectable and evictable. */
export const RERAN_LABEL = "autopilot:reran";

/** The once-ever latch: any comment/review body containing this prefix means
 *  the PR has had its one rerun. Extends the `<!-- autopilot:… -->` marker
 *  convention (needs-human / reviewed / reason:* / review:{slug}:green). */
export const RERUN_MARKER_PREFIX = "<!-- autopilot:rerun:";

/** R-10 / W-1 class: editorial + deploy gates are categorically
 *  rerun-ineligible (C-1: a truncation/deploy gate that fails is a real
 *  finding, never a flake to retry past). */
export const EDITORIAL_INELIGIBLE_RE = /deploy|article|truncat|editorial/i;

const GREEN_CONCLUSIONS = new Set(["success", "neutral", "skipped"]);
// Evidence = a URL, or an issue ref (`#123` / `owner/repo#123`).
const EVIDENCE_RE = /^(https?:\/\/\S+|(?:[\w.-]+\/[\w.-]+)?#\d+)$/;
const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const ENTRY_KEYS = new Set(["check_name", "evidence", "expires"]);

const todayIso = () => new Date().toISOString().slice(0, 10);

/** Validate the allowlist file's entries. Pure; returns { errors, warnings }.
 *  errors  — reject the file (CI red via validate-skills.mjs; runtime throw):
 *            not an array, malformed entry, missing/invalid evidence or
 *            expires, duplicate check_name, or an editorial/deploy-class
 *            check name (categorically ineligible — hard error, never warn).
 *  warnings — an EXPIRED entry: legal in git (history stays reviewable) but
 *            inert at runtime; warn so the operator prunes it. */
export function validateFlakyChecks(entries, { today = todayIso() } = {}) {
  const errors = [];
  const warnings = [];
  if (!Array.isArray(entries)) {
    errors.push("flaky-checks.json must be a JSON array of { check_name, evidence, expires }");
    return { errors, warnings };
  }
  const seen = new Set();
  entries.forEach((e, i) => {
    const at = `entry[${i}]`;
    if (e === null || typeof e !== "object" || Array.isArray(e)) {
      errors.push(`${at} must be an object { check_name, evidence, expires }`);
      return;
    }
    for (const k of Object.keys(e)) {
      if (!ENTRY_KEYS.has(k)) errors.push(`${at} has unknown key "${k}" (allowed: check_name, evidence, expires)`);
    }
    if (typeof e.check_name !== "string" || e.check_name.trim().length === 0) {
      errors.push(`${at} check_name must be a non-empty string (the exact GitHub check-run name)`);
    } else {
      if (EDITORIAL_INELIGIBLE_RE.test(e.check_name)) {
        errors.push(
          `${at} check_name "${e.check_name}" matches the editorial/deploy gate class ` +
            `(${EDITORIAL_INELIGIBLE_RE}) — R-10/W-1-class checks are CATEGORICALLY rerun-ineligible (Epic-019 Story 2c)`,
        );
      }
      const norm = e.check_name.trim().toLowerCase();
      if (seen.has(norm)) errors.push(`${at} duplicate check_name "${e.check_name}"`);
      seen.add(norm);
    }
    if (typeof e.evidence !== "string" || !EVIDENCE_RE.test(e.evidence.trim())) {
      errors.push(
        `${at} evidence must be a URL or issue ref (#123 / owner/repo#123) — ` +
          `every flake exemption cites its evidence; no evidence, no entry (Farah's discipline)`,
      );
    }
    if (typeof e.expires !== "string" || !ISO_DATE_RE.test(e.expires) || Number.isNaN(Date.parse(e.expires))) {
      errors.push(`${at} expires must be a real YYYY-MM-DD date — no evergreen exemptions`);
    } else if (e.expires < today) {
      warnings.push(`${at} "${e.check_name}" expired ${e.expires} — inert at runtime; prune it (or re-evidence a still-live flake)`);
    }
  });
  return { errors, warnings };
}

/** Read + validate the allowlist file. Throws loud (C-4) on an unreadable /
 *  unparseable / invalid file — the caller escalates instead of guessing. */
export function loadAllowlist(path = FLAKY_CHECKS_PATH) {
  const entries = JSON.parse(readFileSync(path, "utf8"));
  const { errors } = validateFlakyChecks(entries);
  if (errors.length > 0) throw new Error(`flaky-checks.json invalid: ${errors.join("; ")}`);
  return entries;
}

/** The unexpired, validated allowlist as a Map(lowercased check_name → entry).
 *  Throws (C-4) if the entries are malformed — a broken allowlist never
 *  silently authorises a rerun. */
export function activeAllowlist(entries, today = todayIso()) {
  const { errors } = validateFlakyChecks(entries, { today });
  if (errors.length > 0) throw new Error(`flaky-checks allowlist invalid: ${errors.join("; ")}`);
  const map = new Map();
  for (const e of entries) {
    if (e.expires >= today) map.set(e.check_name.trim().toLowerCase(), e);
  }
  return map;
}

/** Has this PR already had its one rerun? (prefix match on the audit marker) */
export function hasRerunMarker(bodies) {
  return (bodies ?? []).some((b) => String(b || "").includes(RERUN_MARKER_PREFIX));
}

const sanitizeName = (n) => String(n).replace(/-->/g, "→").replace(/\|/g, "/").trim();

/** The audit marker: rerun ordinal + the machine-readable check names, so
 *  build-pr-metrics-github.mjs can count reruns per check. */
export function rerunMarker(checkNames) {
  return `${RERUN_MARKER_PREFIX}1 checks=${checkNames.map(sanitizeName).join("|")} -->`;
}

const RERUN_MARKER_RE = /<!--\s*autopilot:rerun:\d+\s+checks=([^>]*?)\s*-->/g;

/** Parse every rerun marker in a body → [{ checks: [names] }]. */
export function findRerunMarkers(body) {
  const found = [];
  const re = new RegExp(RERUN_MARKER_RE.source, "g");
  let m;
  while ((m = re.exec(String(body ?? ""))) !== null) {
    found.push({ checks: m[1].split("|").map((s) => s.trim()).filter(Boolean) });
  }
  return found;
}

/** PURE decision core. Given the failing check NAMES, the allowlist entries,
 *  and every comment/review body on the PR (for the once-ever latch):
 *    → { reran: true, checks, evidence }                    trigger the rerun
 *    → { reran: false, escalateWith: "checks-failing", why } escalate normally
 *  Throws (C-4) on ambiguous input (empty/unnamed failing set) or a
 *  malformed allowlist — never a silent pass. */
export function decideRerun({ failingChecks, entries, bodies = [], today = todayIso() } = {}) {
  if (!Array.isArray(failingChecks)) {
    throw new Error("decideRerun: failingChecks must be an array of check names (C-4: ambiguous input never silently passes)");
  }
  const names = failingChecks.map((n) => String(n ?? "").trim());
  if (names.length === 0 || names.some((n) => n.length === 0)) {
    throw new Error("decideRerun: an empty or unnamed failing-check set is ambiguous — refusing to decide (C-4)");
  }
  const escalate = (why) => ({ reran: false, escalateWith: assertReasonCode("checks-failing"), why });

  // Categorical ineligibility first — even an allowlisted editorial gate
  // never reruns (the validator makes such an entry impossible; this is the
  // runtime backstop).
  const editorial = names.filter((n) => EDITORIAL_INELIGIBLE_RE.test(n));
  if (editorial.length > 0) {
    return escalate(`editorial/deploy-class check(s) are categorically rerun-ineligible (R-10/W-1): ${editorial.join(", ")}`);
  }
  const active = activeAllowlist(entries, today); // throws on a malformed allowlist
  const notAllowed = names.filter((n) => !active.has(n.toLowerCase()));
  if (notAllowed.length > 0) {
    return escalate(`failing check(s) not on the unexpired flake allowlist: ${notAllowed.join(", ")} — a rerun needs EVERY failing check allowlisted`);
  }
  if (hasRerunMarker(bodies)) {
    return escalate(
      `this PR already used its one rerun (max ${MAX_RERUNS_PER_PR}; the ${RERUN_MARKER_PREFIX}… --> marker is present) — a rerun that still fails escalates, never retried`,
    );
  }
  return {
    reran: true,
    checks: names,
    evidence: names.map((n) => {
      const e = active.get(n.toLowerCase());
      return { check: n, evidence: e.evidence, expires: e.expires };
    }),
  };
}

/** The visible audit comment: check names + allowlist evidence + the hidden
 *  once-ever marker. A rerun-then-pass stays visible through this forever. */
export function rerunAuditBody(decision) {
  return [
    `**Autopilot flaky-check rerun — 1 of max ${MAX_RERUNS_PER_PR} (Epic-019 Story 2c).**`,
    "",
    "Every failing check is on the evidenced, unexpired flake allowlist" +
      " (workforce/skills/pr-autopilot/flaky-checks.json) — triggering one bounded rerun" +
      " instead of escalating `checks-failing`:",
    "",
    ...decision.evidence.map((e) => `- \`${sanitizeName(e.check)}\` — allowlisted flake (evidence: ${e.evidence}, expires ${e.expires})`),
    "",
    "If the rerun still fails, the next verdict escalates `checks-failing` — never retried." +
      ` A rerun-then-pass stays visible via this comment and the \`${RERAN_LABEL}\` label (never a silent green).`,
    "",
    "— pr-autopilot flaky-rerun (deterministic; see workforce/skills/pr-autopilot/SKILL.md)",
    "",
    rerunMarker(decision.checks),
  ].join("\n");
}

/** Thin-IO wrapper (gh = pr-merge.mjs makeGh client). Re-reads the PR's live
 *  check state, decides via decideRerun, and — only on a rerun decision —
 *  posts the audit marker comment FIRST (the once-ever latch must exist
 *  before any rerun fires), stamps `autopilot:reran`, then triggers:
 *    - POST /actions/runs/{id}/rerun-failed-jobs for each failed workflow run
 *      at the head sha (GitHub Actions checks), and
 *    - POST /check-runs/{id}/rerequest for each failing non-Actions check run.
 *  Returns { reran: true, checks, triggered } or
 *          { reran: false, escalateWith: "checks-failing", why }.
 *  Throws (C-4) on any ambiguous/half-failed state — the caller escalates. */
export async function attemptFlakyRerun(gh, repo, prNumber, { entries = loadAllowlist(), today = todayIso() } = {}) {
  const escalate = (why) => ({ reran: false, escalateWith: assertReasonCode("checks-failing"), why });
  if (!Array.isArray(entries) || entries.length === 0) {
    return escalate("the flake allowlist is empty — nothing is rerun-eligible");
  }

  const { status, json: p } = await gh("GET", `/repos/${repo}/pulls/${prNumber}`);
  if (status !== 200 || !p?.head?.sha) throw new Error(`GET pull #${prNumber} → HTTP ${status} — cannot determine head sha (C-4)`);

  const { status: cs, json: cj } = await gh("GET", `/repos/${repo}/commits/${p.head.sha}/check-runs?per_page=100`);
  if (cs !== 200 || !Array.isArray(cj?.check_runs)) throw new Error(`GET check-runs for #${prNumber} → HTTP ${cs} — check state unknown (C-4)`);
  const runs = cj.check_runs;
  const pending = runs.filter((c) => c.status !== "completed");
  if (pending.length > 0) {
    return escalate(`check state ambiguous: ${pending.length} check run(s) not completed (e.g. '${pending[0].name}') — not rerunning`);
  }
  const failing = runs.filter((c) => !GREEN_CONCLUSIONS.has(c.conclusion));
  if (failing.length === 0) {
    return escalate("no failing check runs found at rerun time — nothing to rerun (re-verdict instead)");
  }

  // Once-ever latch: scan every comment + review body for the rerun marker.
  const [c, rv] = await Promise.all([
    gh("GET", `/repos/${repo}/issues/${prNumber}/comments?per_page=100`),
    gh("GET", `/repos/${repo}/pulls/${prNumber}/reviews?per_page=100`),
  ]);
  const bodies = [
    ...(Array.isArray(c.json) ? c.json.map((x) => x.body) : []),
    ...(Array.isArray(rv.json) ? rv.json.map((x) => x.body) : []),
  ];

  const decision = decideRerun({ failingChecks: failing.map((x) => x.name), entries, bodies, today });
  if (!decision.reran) return decision;

  // Audit marker FIRST: if this comment cannot land, no rerun fires — a crash
  // after this point can forfeit the one rerun but never duplicate it.
  const cm = await gh("POST", `/repos/${repo}/issues/${prNumber}/comments`, { body: rerunAuditBody(decision) });
  if (cm.status !== 201) {
    throw new Error(`rerun audit comment on #${prNumber} → HTTP ${cm.status} — refusing to rerun without the max-1 latch (C-4)`);
  }
  // Metrics label (best-effort: a label hiccup must not lose the rerun the
  // marker already committed us to).
  const lc = await gh("POST", `/repos/${repo}/labels`, {
    name: RERAN_LABEL,
    color: "fbca04", // yellow — telemetry, not a work queue
    description: "Epic-019 Story 2c — this PR's known-flaky failing checks were auto-rerun once (audit comment carries the evidence).",
  });
  if (lc.status !== 201 && lc.status !== 422) console.error(`flaky-rerun: WARN ensure label "${RERAN_LABEL}" → HTTP ${lc.status}`);
  const lr = await gh("POST", `/repos/${repo}/issues/${prNumber}/labels`, { labels: [RERAN_LABEL] });
  if (lr.status !== 200) console.error(`flaky-rerun: WARN could not label #${prNumber} ${RERAN_LABEL} → HTTP ${lr.status}`);

  // Trigger. GitHub Actions checks rerun via their workflow runs; anything
  // else (external check apps) via check-run rerequest.
  let triggered = 0;
  const hasActionsFailing = failing.some((x) => (x.app?.slug || "") === "github-actions");
  if (hasActionsFailing) {
    const { status: ws, json: wj } = await gh("GET", `/repos/${repo}/actions/runs?head_sha=${p.head.sha}&per_page=100`);
    if (ws !== 200 || !Array.isArray(wj?.workflow_runs)) throw new Error(`GET workflow runs for ${p.head.sha} → HTTP ${ws} — cannot trigger rerun (C-4)`);
    for (const run of wj.workflow_runs) {
      if (run.status === "completed" && !GREEN_CONCLUSIONS.has(run.conclusion)) {
        const rr = await gh("POST", `/repos/${repo}/actions/runs/${run.id}/rerun-failed-jobs`);
        if (rr.status !== 201) throw new Error(`rerun-failed-jobs on workflow run ${run.id} → HTTP ${rr.status} — half-triggered rerun, escalate (C-4)`);
        triggered++;
      }
    }
  }
  for (const x of failing) {
    if ((x.app?.slug || "") !== "github-actions") {
      const rr = await gh("POST", `/repos/${repo}/check-runs/${x.id}/rerequest`);
      if (rr.status !== 201) throw new Error(`rerequest check-run ${x.id} ('${x.name}') → HTTP ${rr.status} — half-triggered rerun, escalate (C-4)`);
      triggered++;
    }
  }
  if (triggered === 0) {
    throw new Error("decided to rerun but found nothing to trigger (no failed workflow run, no rerequestable check run) — ambiguous state, escalate (C-4)");
  }
  return { reran: true, checks: decision.checks, triggered };
}

