#!/usr/bin/env node
// pr-autopilot/pr-merge.mjs — the shared, deterministic **consensus merge engine**
// for the workforce's R-N10 delegated-external-merge lane (widened by adr-0010,
// 2026-06-17, superseding the original Dependabot-only safe-class predicate).
//
// The merge predicate is now: a PR is mergeable iff it touches **no L0/L1 path**
// of the TARGET repo's own governance (read from that repo's docs/governance.md),
// is open + mergeable (state "clean" OR "draft" — adr-0014), has **all required
// checks green**, carries **no human CHANGES_REQUESTED**, and the routing
// persona's nominated reviewers — **at least MIN_REVIEWERS (3) distinct
// personas** (operator directive 2026-06-29) — have each posted their lens
// review (the unanimous-green consensus). A panel of fewer than 3 green
// reviewers is refused. L0/L1-touching PRs are never merged — they
// escalate to a human (the operator's final call). A **draft** that clears the
// predicate is a first-class merge target: applyDecisions marks it Ready for
// Review (GraphQL) immediately before the merge PUT, since GitHub refuses to
// merge a draft directly (adr-0014).
//
// R-N10 (workforce/docs/governance.md) clause 2: this engine RE-VERIFIES the
// predicate SERVER-SIDE and FAILS CLOSED. A decision marked action:"merge" is
// honoured only if, at apply time, every predicate clause re-passes against the
// live PR. Anything it cannot positively confirm — including an unreadable /
// marker-less target governance doc (so the L0/L1 set is unknown) — is a REFUSAL,
// never a merge. Escalations (issue filing) are unconditional.
//
// Source of truth for "what is L0/L1": the TARGET repo's own statute, per the
// operator direction (adr-0010). The engine fetches `docs/governance.md`
// (override: env GOVERNANCE_PATH) and extracts the path globs declared between
//   <!-- autopilot:l0l1-paths -->  …  <!-- /autopilot:l0l1-paths -->
// (one `- <glob>` per line). If that block is absent or empty, the L0/L1 set is
// UNKNOWN and every merge fails closed (route/review/verdict still run; the
// verdict hands off). This keeps the delegation in the maintainer's repo, never
// self-asserted by the workforce (R-N10 clause 1).
//
// CLI usage (both callers invoke this exact surface):
//   TOKEN=<github.token> node .../pr-merge.mjs \
//     --repo <owner>/<repo> --decisions /tmp/decisions.json [--skill-version x.y.z]
//
// Decisions file shape:
//   { "decisions": [
//       { "pr": 553, "action": "merge",
//         "comment": "<verdict / advisory-cited merge comment>",
//         "squash_subject": "feat: … (#553)",
//         "squash_body": "Unanimous reviewer sign-off (dario, ren, mateo). No L0/L1 surface.",
//         "reviewers": ["dario", "ren", "mateo"] },   // ≥3 distinct (MIN_REVIEWERS)
//       { "pr": 506, "action": "escalate",
//         "issue_title": "Hold #506: touches L0/L1",
//         "issue_body": "<why held + next step>",
//         "issue_labels": ["governance"] }   // ESCALATION_LABEL is always added
//   ] }
//
// Every escalation issue (and, via pr-autopilot-post.mjs --label, every PR
// handed off to a human) is stamped with ESCALATION_LABEL ("autopilot:needs-
// human") so the operator can list the whole human-decision queue at once.
//
// Exit codes: 0 all applied · 1 bad args/file · 2 a decision refused or a GitHub
// write rejected · 3 network/unexpected.

import { ensureProxyAwareEntry } from "../../../scripts/lib/proxy-bootstrap.mjs";
ensureProxyAwareEntry(import.meta.url);

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { assertReasonCode, isAuthorLaneCode, reasonLabel, reasonMarker, refusalReasonCode } from "./escalation-reasons.mjs";

const GOVERNANCE_PATH = process.env["GOVERNANCE_PATH"] || "docs/governance.md";
const L0L1_OPEN = "<!-- autopilot:l0l1-paths -->";
const L0L1_CLOSE = "<!-- /autopilot:l0l1-paths -->";

// The canonical, searchable label stamped on every PR/issue this skill hands
// off to a human (a 🔴 verdict, a non-consensus PR, a tracking issue, or — the
// common one — a 🟢 PR that touches the target repo's governance L0/L1). The
// operator finds the full human-decision queue with `is:open label:<this>`.
// pr-autopilot-post.mjs stamps it on hand-off PRs; this engine stamps it on
// every escalation issue it files.
export const ESCALATION_LABEL = "autopilot:needs-human";
const ESCALATION_LABEL_COLOR = "b60205"; // red — "an autopilot decision needs a human"

// The companion "this was reviewed" marker, stamped *alongside* ESCALATION_LABEL
// only on a 🟢 unanimous-green hand-off — a PR that reached reviewer consensus
// and is merge-ready, held back from an autonomous merge solely by a human gate
// (the target repo's L0/L1 boundary, or a missing R-N10 delegation). It lets the
// operator separate "reviewed + merge-ready, just my final call" from a 🔴 /
// cycle-capped / non-consensus escalation that still needs work — both carry
// ESCALATION_LABEL, only the former carries this. It is NOT put on the engine's
// refused-decision tracking issues (those never reached green). Single-sourced
// here; pr-autopilot-post.mjs imports it (and a --reviewed flag) to stamp it.
export const REVIEWED_LABEL = "autopilot:reviewed";

// The AUTHOR lane (adr-0022). Stamped instead of ESCALATION_LABEL when the
// hand-off's cause is agent-fixable — a merge conflict, an out-of-date branch,
// or open blocking lens findings. It is the `pr-remediate` cadence's work
// queue (`is:open label:autopilot:needs-author`), not the operator's.
//
// It is an INTERIM state, and bounded like every other one: a PR that sits here
// without its head moving past the sweep's --author-stale-hours is escalated to
// the human lane by pr-autopilot-sweep.mjs (`author-stale`), as is one that
// exhausts the remediation attempt cap. The two-outcome contract is unchanged —
// merged or escalated remain the only terminal states; this names who works the
// PR while it is in neither.
export const AUTHOR_LABEL = "autopilot:needs-author";

// The author lane's hidden marker — the same mechanical pairing the human lane
// has (`<!-- autopilot:needs-human -->` ↔ `autopilot:needs-human`), so a body
// carrying it stamps the label even when the flag is forgotten, and the sweep
// can recognise the lane from PR state alone. Defined here, next to the label,
// because pr-autopilot-post.mjs imports this module (not the other way round —
// that would be a cycle).
export const AUTHOR_MARKER = "<!-- autopilot:needs-author -->";

// Attempt-counter marker for the author lane: `<!-- autopilot:remediation:<n> -->`.
// The lane is bounded by counting these — REMEDIATION_CAP attempts, then the PR
// escalates to the human lane with `remediation-cap-exceeded`.
//
// **The marker is CLAIMED BEFORE the attempt, never written after it**
// (`pr-remediate-post.mjs --claim`), which is the same once-ever-latch idiom
// flaky-rerun.mjs uses for its bounded rerun. The reason is `wf:farah`'s F1 on
// #518: a counter the bounded thing writes on success is enforced by the thing
// it bounds. Written afterwards, a cadence that dies mid-attempt — after pushing
// to the head branch, before recording — would refresh the PR's `updated_at`
// (resetting the sweep's staleness clock) while consuming no attempt, and could
// retry the same failing resolution forever. Claiming first inverts that: a
// death costs an attempt. Over-counting a crashed run is the safe direction;
// under-counting an infinite one is not.
//
// Kept next to the lane's other constants so the counter, the marker and the cap
// cannot drift apart.
export const REMEDIATION_CAP = 3;
const REMEDIATION_MARKER_RE = /<!--\s*autopilot:remediation:(\d+)\s*-->/g;

/** Highest remediation-attempt number recorded across the PR's comment bodies
 *  (0 = never attempted). Pure + exported so the bound is unit-tested. */
export function countRemediationAttempts(bodies = []) {
  let max = 0;
  for (const b of bodies) {
    const re = new RegExp(REMEDIATION_MARKER_RE.source, "g");
    let m;
    while ((m = re.exec(String(b ?? ""))) !== null) max = Math.max(max, Number(m[1]) || 0);
  }
  return max;
}

/** The marker for attempt `n`. Throws past the cap — an unbounded retry loop is
 *  exactly what this lane must not become (C-4). */
export function remediationMarker(n) {
  const attempt = Number(n);
  if (!Number.isInteger(attempt) || attempt < 1 || attempt > REMEDIATION_CAP) {
    throw new Error(
      `remediation attempt ${n} is outside 1..${REMEDIATION_CAP} — a PR past the cap escalates to the human lane ` +
        `with reason "remediation-cap-exceeded" (adr-0022), it is never retried again.`,
    );
  }
  return `<!-- autopilot:remediation:${attempt} -->`;
}

// Minimum reviewer-panel size for an autonomous merge (operator directive
// 2026-06-29). A merge is honoured only when at least this many DISTINCT
// reviewer personas have each posted their `<!-- autopilot:review:{slug}:green
// -->` marker — a lone-reviewer (or two-reviewer) sign-off is no longer a
// consensus the engine will merge on. This TIGHTENS the R-N10 / adr-0010
// predicate (more reviewers required, never fewer); it does not widen what may
// merge. verifyMergeable() fails closed below this floor; the SKILL.md routing
// contract mirrors it by mandating a ≥3-persona panel at nomination time.
export const MIN_REVIEWERS = 3;

// Create labels if they do not already exist (idempotent: an existing label
// returns 422, which we ignore). Lets a target repo that has never seen the
// escalation label still receive it without a manual pre-create step.
export async function ensureLabels(gh, repo, names) {
  for (const name of names) {
    // The author lane is a different queue from the human one and must not be
    // created wearing the escalation label's red "a human's call" description —
    // an operator filtering by colour/description would read it as their work.
    const meta =
      name === AUTHOR_LABEL
        ? {
            color: "fbca04", // amber — in-flight, agent-owned
            description:
              "Autopilot found an agent-fixable defect (conflict / out-of-date branch / open review findings). The pr-remediate cadence owns it; bounded — it escalates to autopilot:needs-human if remediation stalls or caps out.",
          }
        : {
            color: ESCALATION_LABEL_COLOR,
            description: "Autopilot handed this off — a human's call (merge / governance L0/L1 / blocked).",
          };
    const { status } = await gh("POST", `/repos/${repo}/labels`, { name, ...meta });
    if (status !== 201 && status !== 422) {
      console.error(`pr-merge: WARN could not ensure label "${name}" (HTTP ${status}) — continuing`);
    }
  }
}

// W-1 editorial guard: a degraded body fails loud here, never lands on GitHub.
const ARTEFACTS = ["as an ai", "i apologize", "i'm sorry", "certainly!", "here is the", "here's the"];
export function w1(text, label) {
  const t = (text || "").trim();
  if (!t) throw { code: 2, msg: `${label} is empty (W-1)` };
  const head = t.slice(0, 50).toLowerCase();
  if (ARTEFACTS.some((a) => head.startsWith(a))) throw { code: 2, msg: `${label} opens with an LLM-failure artefact (W-1): "${head}"` };
  return t;
}

// Translate a leading-slash-free path glob (`**`, `*`, `?`) into an anchored
// RegExp. `**` matches across slashes; `*` matches within a path segment.
export function globToRegExp(glob) {
  let re = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*") {
      if (glob[i + 1] === "*") { re += ".*"; i++; if (glob[i + 1] === "/") i++; }
      else re += "[^/]*";
    } else if (c === "?") re += "[^/]";
    else if ("\\^$.|+()[]{}".includes(c)) re += "\\" + c;
    else re += c;
  }
  return new RegExp(`(^|/)${re}$`, "i");
}

// Fetch the TARGET repo's governance doc and extract the declared L0/L1 path
// globs. Returns { ok, patterns, why }. ok=false ⇒ the L0/L1 set is unknown ⇒
// the caller fails every merge closed (route/review still run).
export async function resolveL0L1Paths(gh, repo, ref) {
  const path = GOVERNANCE_PATH;
  const q = ref ? `?ref=${encodeURIComponent(ref)}` : "";
  const { status, json } = await gh("GET", `/repos/${repo}/contents/${encodeURIComponent(path).replace(/%2F/g, "/")}${q}`);
  if (status !== 200 || typeof json?.content !== "string") {
    return { ok: false, patterns: [], why: `cannot read target governance ${path} (HTTP ${status}) — L0/L1 set unknown, failing merge closed` };
  }
  const md = Buffer.from(json.content, json.encoding === "base64" ? "base64" : "utf8").toString("utf8");
  const start = md.indexOf(L0L1_OPEN);
  const end = md.indexOf(L0L1_CLOSE, start + 1);
  if (start === -1 || end === -1) {
    return { ok: false, patterns: [], why: `${path} declares no ${L0L1_OPEN} block — L0/L1 set unknown, failing merge closed` };
  }
  const block = md.slice(start + L0L1_OPEN.length, end);
  const globs = block
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.startsWith("- "))
    .map((l) => l.slice(2).trim())
    .filter(Boolean);
  if (globs.length === 0) {
    return { ok: false, patterns: [], why: `${path} L0/L1 block is empty — failing merge closed` };
  }
  return { ok: true, patterns: globs.map(globToRegExp), why: `${globs.length} L0/L1 glob(s) from ${path}` };
}

// Build a thin GitHub REST client bound to one token + repo.
export function makeGh({ token, api = process.env["GITHUB_API_URL"] || "https://api.github.com", userAgent = "workforce-pr-merge" }) {
  return async function gh(method, path, body) {
    let res;
    try {
      res = await fetch(`${api}${path}`, {
        method,
        headers: {
          authorization: `Bearer ${token}`,
          accept: "application/vnd.github+json",
          "x-github-api-version": "2022-11-28",
          "user-agent": userAgent,
          ...(body ? { "content-type": "application/json" } : {}),
        },
        body: body ? JSON.stringify(body) : undefined,
      });
    } catch (e) { throw { code: 3, msg: `network error on ${method} ${path}: ${e?.message || e}` }; }
    const text = await res.text().catch(() => "");
    let json; try { json = text ? JSON.parse(text) : {}; } catch { json = { _raw: text }; }
    return { status: res.status, json };
  };
}

// W-4 hard cycle cap (FU-004 / dev-process.md §"cycle counter").
// The routing comment opening line is (SKILL.md §Step 2 template):
//   **<PersonaName> — cycle N of ≤ M.**   ("—" = U+2014, "≤" = U+2264)
// countRouterCycles() scans bodies for this pattern and returns the highest N.
// verifyMergeable() refuses a merge when that maximum exceeds W4_CYCLE_CAP
// (cycle > 7 == process breakdown; W-4: fail loud, escalate to human).
export const W4_CYCLE_CAP = 7;
const ROUTING_CYCLE_RE = /\*\*[\w ]+\s*—\s*cycle\s+(\d+)\s+of\s+≤\s*\d+/u;
export function countRouterCycles(bodies) {
  let max = 0;
  for (const b of bodies) {
    if (typeof b !== "string") continue;
    const m = ROUTING_CYCLE_RE.exec(b);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return max;
}

// A reviewer persona's green sign-off has landed iff a review/comment body
// carries that persona's EXACT structured marker (adr-0010 / Sana B1 hardening,
// 2026-06-17): `<!-- autopilot:review:{slug}:green -->`. The routing persona
// embeds this token in each nominated reviewer's posted review when that lens is
// non-blocking. An exact hidden-comment match removes the two failure modes of
// the old byline regex: a differently-formatted sign-off no longer reads as
// "missing" by accident, and prose that merely names the persona can no longer
// read as a green vote. Absence of the marker fails closed (no merge).
export function reviewerGreenMarker(slug) {
  return `<!-- autopilot:review:${String(slug).toLowerCase()}:green -->`;
}
export function reviewerSignedOff(slug, reviewBodies) {
  const marker = reviewerGreenMarker(slug);
  return reviewBodies.some((b) => (b || "").toLowerCase().includes(marker));
}

// Epic-019 Story 1: verdict-time L0/L1 computation. The merge leg computes the
// L0/L1 clause inside verifyMergeable; ESCALATIONS need the same answer so the
// reason funnel can split eligible (non-L0/L1) hand-offs from structural ones.
// This helper replicates the two clauses read-only — same source of truth
// (resolveL0L1Paths, the TARGET repo's own statute) and same fail-closed
// semantics: an unreadable/markerless governance doc returns known:false (the
// L0/L1 set is UNKNOWN — callers escalate without guessing eligibility). It is
// deliberately NOT wired into verifyMergeable: the R-N10 predicate's decision
// flow stays byte-identical.
export async function prTouchesL0L1(gh, repo, prNumber, baseRef) {
  const l0l1 = await resolveL0L1Paths(gh, repo, baseRef);
  if (!l0l1.ok) return { known: false, touches: null, why: l0l1.why };
  const { status, json: files } = await gh("GET", `/repos/${repo}/pulls/${prNumber}/files?per_page=100`);
  if (status !== 200 || !Array.isArray(files)) {
    return { known: false, touches: null, why: `GET files -> HTTP ${status} — L0/L1 surface unknown` };
  }
  const hit = files.find((f) => l0l1.patterns.some((re) => re.test(f.filename)));
  return hit
    ? { known: true, touches: true, why: `touches L0/L1 path ${hit.filename}` }
    : { known: true, touches: false, why: `no L0/L1 surface` };
}

// Epic-019 Story 1: a refused merge is the engine's hand-off leg — record WHY
// on the PR itself (an `autopilot:reason:<code>` label + the hidden marker in
// a comment) so the escalation-reason funnel renders with zero manual
// counting. Pure telemetry: it runs strictly AFTER the refusal is decided
// (the R-N10 predicate is untouched), and its own GitHub-write failures are
// logged, not fatal — a telemetry hiccup must not mask a correct refusal.
// The code mapping itself stays C-4-loud: reasonLabel/reasonMarker throw on a
// code outside the taxonomy.
export async function emitRefusalReason(gh, repo, pr, why) {
  const code = refusalReasonCode(why);
  // adr-0022: a refusal whose cause is agent-fixable (a conflict with the base,
  // an out-of-date branch) is routed to the AUTHOR lane here, at the refusal
  // itself — that is where the cause is first known, so the PR joins
  // `pr-remediate`'s queue on the same tick instead of waiting for a session to
  // notice. The predicate is untouched: this still refuses the merge.
  const authorLane = isAuthorLaneCode(code);
  const labels = [reasonLabel(code), ...(authorLane ? [AUTHOR_LABEL] : [])];
  const body = [
    `**Autopilot merge engine — refusal reason \`${code}\`.** ${why}`,
    "",
    authorLane
      ? "Agent-fixable — handing to the **author lane** (`autopilot:needs-author`). The `pr-remediate` cadence picks this up, pushes the fix to the head branch, and the next autopilot tick re-verdicts. If it cannot (attempt cap, or a resolution only a human should make) it escalates to `autopilot:needs-human` with its own reason."
      : "(Epic-019 escalation-reason telemetry — wiring, not reviewer performance; see workforce/docs/pr-escalation-reasons.md.)",
    "",
    reasonMarker(code, code === "other" ? why : ""),
    ...(authorLane ? [AUTHOR_MARKER] : []),
  ].join("\n");
  await ensureLabels(gh, repo, labels);
  const l = await gh("POST", `/repos/${repo}/issues/${pr}/labels`, { labels });
  if (l.status !== 200) console.error(`pr-merge: WARN reason label(s) "${labels.join(", ")}" on #${pr} → HTTP ${l.status}`);
  const c = await gh("POST", `/repos/${repo}/issues/${pr}/comments`, { body });
  if (c.status !== 201) console.error(`pr-merge: WARN reason comment on #${pr} → HTTP ${c.status}`);
  return code;
}

// Server-side predicate re-check. Returns {ok, why, sha}.
export async function verifyMergeable(gh, repo, pr, decision) {
  const { status, json: p } = await gh("GET", `/repos/${repo}/pulls/${pr}`);
  if (status !== 200) return { ok: false, why: `GET pull ${pr} -> HTTP ${status}` };
  if (p.state !== "open") return { ok: false, why: `PR #${pr} is ${p.state}` };
  // No own-repo special case (adr-0011): the workforce's own repo is a normal
  // delegated target. The single boundary is the L0/L1 path set below — read
  // from the TARGET repo's own governance — so a governance/identity change
  // still escalates while a reviewed, non-L0/L1 PR merges, own repo or external.
  // Per-PR maintainer off-switch: an `autopilot:off` label pauses this PR
  // (fail-closed). The repo-wide off-switch is emptying the target's
  // autopilot:l0l1-paths block (→ unknown set → refuse, see resolveL0L1Paths).
  if (Array.isArray(p.labels) && p.labels.some((l) => (l?.name || "").toLowerCase() === "autopilot:off")) {
    return { ok: false, why: `autopilot:off label set — paused by maintainer` };
  }
  // adr-0014: a draft is a first-class merge target. GitHub reports a ready PR
  // as mergeable_state "clean" and a draft as "draft"; both are acceptable here
  // (a draft is auto-marked Ready for Review just before the merge PUT in
  // applyDecisions). Every OTHER state (dirty/blocked/behind/unstable) is still
  // refused, and `mergeable` must still be true — a draft with a real conflict
  // is out.
  if (p.mergeable !== true || !["clean", "draft"].includes(p.mergeable_state)) return { ok: false, why: `not mergeable (mergeable=${p.mergeable}, state=${p.mergeable_state})` };

  // L0/L1 guard — sourced from the TARGET repo's own governance (adr-0010).
  const l0l1 = await resolveL0L1Paths(gh, repo, p.base?.ref);
  if (!l0l1.ok) return { ok: false, why: l0l1.why };
  const { status: fs, json: files } = await gh("GET", `/repos/${repo}/pulls/${pr}/files?per_page=100`);
  if (fs !== 200 || !Array.isArray(files)) return { ok: false, why: `GET files -> HTTP ${fs}` };
  for (const f of files) {
    if (l0l1.patterns.some((re) => re.test(f.filename))) {
      return { ok: false, why: `touches L0/L1 path ${f.filename} — escalate to human (operator's final call)` };
    }
  }

  // All required checks green.
  const { status: cs, json: checks } = await gh("GET", `/repos/${repo}/commits/${p.head.sha}/check-runs?per_page=100`);
  if (cs !== 200) return { ok: false, why: `GET check-runs -> HTTP ${cs}` };
  for (const c of checks.check_runs || []) {
    if (c.status !== "completed") return { ok: false, why: `check '${c.name}' is ${c.status}` };
    if (!["success", "neutral", "skipped"].includes(c.conclusion)) return { ok: false, why: `check '${c.name}' = ${c.conclusion}` };
  }

  // Unanimous-green consensus: no human CHANGES_REQUESTED, and every nominated
  // reviewer has posted their lens review.
  const { status: rs, json: reviews } = await gh("GET", `/repos/${repo}/pulls/${pr}/reviews?per_page=100`);
  if (rs !== 200 || !Array.isArray(reviews)) return { ok: false, why: `GET reviews -> HTTP ${rs}` };
  if (reviews.some((r) => r.state === "CHANGES_REQUESTED")) return { ok: false, why: `a reviewer has CHANGES_REQUESTED — not consensus-green` };
  // Distinct reviewer slugs (case-folded, de-duped) — listing the same persona
  // three times is one reviewer, not a panel of three.
  const reviewers = Array.isArray(decision?.reviewers)
    ? [...new Set(decision.reviewers.filter((s) => typeof s === "string" && s).map((s) => s.trim().toLowerCase()).filter(Boolean))]
    : [];
  const { status: ics, json: comments } = await gh("GET", `/repos/${repo}/issues/${pr}/comments?per_page=100`);
  const bodies = [
    ...reviews.map((r) => r.body),
    ...(ics === 200 && Array.isArray(comments) ? comments.map((c) => c.body) : []),
  ];
  // FU-004: W-4 hard cycle cap — a PR that has reached cycle > W4_CYCLE_CAP is
  // a process breakdown; refuse the merge and hand off to a human.
  const cycle = countRouterCycles(bodies);
  if (cycle > W4_CYCLE_CAP) {
    return { ok: false, why: `review reached cycle ${cycle}, exceeding the W-4 hard cap of ${W4_CYCLE_CAP} — process breakdown, escalate to human` };
  }
  const missing = reviewers.filter((slug) => !reviewerSignedOff(slug, bodies));
  if (missing.length > 0) return { ok: false, why: `missing green marker(s) from ${missing.join(", ")} (expected ${reviewerGreenMarker(missing[0])}) — consensus not reached` };
  // Minimum-panel floor (operator directive 2026-06-29): a merge requires at
  // least MIN_REVIEWERS distinct unanimous-green reviewers. Checked last so a
  // more specific reason (L0/L1, CHANGES_REQUESTED, a missing marker) surfaces
  // first; an empty or under-sized green panel falls through to here.
  if (reviewers.length < MIN_REVIEWERS) return { ok: false, why: `only ${reviewers.length} distinct reviewer(s) signed off — a merge requires a panel of at least ${MIN_REVIEWERS} unanimous-green reviewers (operator directive 2026-06-29); under-reviewed merge refused` };

  // `draft` + `nodeId` let applyDecisions flip a green draft Ready for Review
  // before the merge PUT (adr-0014 — GitHub refuses to merge a draft directly).
  return { ok: true, why: `consensus-green, no L0/L1 surface (${reviewers.join(", ")})`, sha: p.head.sha, draft: p.draft === true, nodeId: p.node_id };
}

// Apply one decisions payload. Returns { merged, escalated, refused }.
export async function applyDecisions(gh, repo, decisions) {
  let refused = 0, merged = 0, escalated = 0;

  for (const d of decisions) {
    const pr = d.pr;
    if (d.action === "escalate") {
      const title = w1(d.issue_title, `#${pr} issue_title`);
      let body = w1(d.issue_body, `#${pr} issue_body`);
      // Always stamp the canonical escalation label so the operator can find
      // every human-decision item with one search, in addition to any
      // PR-specific labels the caller supplied.
      const labels = [...new Set([...(Array.isArray(d.issue_labels) ? d.issue_labels : []), ESCALATION_LABEL])];
      // Epic-019: an escalation may declare its reason code (`reason_code`, plus
      // `reason_text` — mandatory for "other"). Validated loud (C-4: an unknown
      // code throws via assertReasonCode) and carried as label + hidden marker.
      if (d.reason_code) {
        assertReasonCode(d.reason_code);
        labels.push(reasonLabel(d.reason_code));
        body = `${body.trimEnd()}\n\n${reasonMarker(d.reason_code, d.reason_text || "")}`;
      }
      await ensureLabels(gh, repo, labels);
      const { status, json } = await gh("POST", `/repos/${repo}/issues`, { title, body, labels });
      if (status === 201) { escalated++; console.error(`pr-merge: escalated #${pr} -> issue ${json.html_url}`); }
      else { refused++; console.error(`pr-merge: FAILED to file issue for #${pr}: HTTP ${status} ${JSON.stringify(json).slice(0, 300)}`); }
      continue;
    }
    if (d.action !== "merge") { refused++; console.error(`pr-merge: #${pr} unknown action "${d.action}"`); continue; }

    // ── R-N10 fail-closed gate (adr-0010 widened predicate) ─────────────────
    const comment = w1(d.comment, `#${pr} comment`);
    const subject = w1(d.squash_subject, `#${pr} squash_subject`);
    const verdict = await verifyMergeable(gh, repo, pr, d);
    if (!verdict.ok) {
      refused++; console.error(`pr-merge: REFUSE merge #${pr}: ${verdict.why}`);
      // Epic-019: stamp the refusal's reason code on the PR (label + marker).
      // Best-effort — a network failure here must not mask the refusal itself.
      try { await emitRefusalReason(gh, repo, pr, verdict.why); }
      catch (e) { console.error(`pr-merge: WARN could not emit refusal reason for #${pr}: ${e?.msg || e?.message || e}`); }
      continue;
    }

    // adr-0014: drafts are merge-eligible. GitHub refuses to merge a draft, so
    // flip it Ready for Review first (GraphQL — there is no REST endpoint; the
    // REST "Update a pull request" endpoint has no `draft` field). Do this
    // BEFORE any merge-intent side effect (comment/approve) so a failure to
    // un-draft leaves no misleading "merging" trail. Fail closed: if the PR is
    // still a draft after the mutation, do not merge.
    //
    // NOTE: this path is a FALLBACK and normally does not run. A CCR session's
    // raw HTTPS to api.github.com is served by the agent proxy, which serves no
    // GraphQL at all — even `{viewer{login}}` returns 403 "This GraphQL query is
    // not enabled for this session". A deterministic script has only raw HTTPS,
    // so it can never make this call from a cadence fire. SKILL.md Step 5
    // therefore requires the ROUTER SESSION to un-draft via the GitHub MCP
    // connector (server-side, outside that proxy) before invoking this engine,
    // which leaves verdict.draft false here. The mutation is kept for callers
    // that do have GraphQL egress (a local operator run).
    if (verdict.draft) {
      // Epic-019: every refusal must stamp its reason code, or the escalation
      // telemetry cannot see it. This path used to `continue` without calling
      // emitRefusalReason(), unlike the predicate path above — so a draft-flip
      // refusal left no label and filed no issue, and the router had to carry
      // the reason code by hand (#542 / #545 / #550).
      const refuseDraft = async (why) => {
        refused++; console.error(`pr-merge: REFUSE merge #${pr}: ${why}`);
        try { await emitRefusalReason(gh, repo, pr, why); }
        catch (e) { console.error(`pr-merge: WARN could not emit refusal reason for #${pr}: ${e?.msg || e?.message || e}`); }
      };
      if (!verdict.nodeId) { await refuseDraft("draft PR but no node id to mark Ready"); continue; }
      const rd = await gh("POST", `/graphql`, {
        query: "mutation($id:ID!){markPullRequestReadyForReview(input:{pullRequestId:$id}){pullRequest{isDraft}}}",
        variables: { id: verdict.nodeId },
      });
      const stillDraft = rd?.json?.data?.markPullRequestReadyForReview?.pullRequest?.isDraft;
      if (rd.status !== 200 || rd?.json?.errors || stillDraft !== false) {
        await refuseDraft(`could not mark draft Ready for Review (HTTP ${rd.status} ${JSON.stringify(rd.json).slice(0, 200)})`); continue;
      }
      console.error(`pr-merge: #${pr} was a draft — marked Ready for Review (adr-0014), proceeding to merge`);
    }

    const c = await gh("POST", `/repos/${repo}/issues/${pr}/comments`, { body: comment });
    if (c.status !== 201) { refused++; console.error(`pr-merge: REFUSE merge #${pr}: comment failed HTTP ${c.status}`); continue; }
    // The native GitHub APPROVE is a courtesy/visibility step and the
    // branch-protection satisfier for PRs authored by a DIFFERENT identity
    // (Dependabot, external contributors). It is NOT the workforce's consensus
    // gate: verifyMergeable() already re-verified the green-marker consensus +
    // checks + L0/L1 server-side, and the merge PUT below re-enforces branch
    // protection authoritatively. The workforce authors most PRs under the SAME
    // identity it merges with, where GitHub forbids a self-approve (422 "Can not
    // approve your own pull request") — treating that as fatal stalled every
    // green own-identity PR at the approve step (#361). So approve is
    // best-effort: log a non-200 and proceed. The merge PUT is the real gate and
    // fails loud if an approving review were genuinely required by protection.
    const rv = await gh("POST", `/repos/${repo}/pulls/${pr}/reviews`, { event: "APPROVE", body: "Autopilot consensus-green merge (R-N10 / adr-0010): unanimous reviewer sign-off, no L0/L1 surface." });
    if (rv.status !== 200) {
      const selfApprove = rv.status === 422 && JSON.stringify(rv.json).toLowerCase().includes("can not approve your own pull request");
      console.error(
        selfApprove
          ? `pr-merge: #${pr} self-approve not possible (own-identity PR) — consensus is the verified green markers; proceeding to merge`
          : `pr-merge: #${pr} WARN approve returned HTTP ${rv.status} ${JSON.stringify(rv.json).slice(0, 200)} — approve is advisory; proceeding (the merge PUT is the gate)`,
      );
    }
    const mg = await gh("PUT", `/repos/${repo}/pulls/${pr}/merge`, { merge_method: "squash", sha: verdict.sha, commit_title: subject, commit_message: d.squash_body || "" });
    if (mg.status === 200) { merged++; console.error(`pr-merge: MERGED #${pr} (${verdict.why})`); }
    else {
      refused++; console.error(`pr-merge: merge #${pr} REJECTED HTTP ${mg.status}: ${JSON.stringify(mg.json).slice(0, 300)}`);
      // Epic-019: a rejected merge PUT is also a refusal exit — record it.
      try { await emitRefusalReason(gh, repo, pr, `merge PUT rejected HTTP ${mg.status}`); }
      catch (e) { console.error(`pr-merge: WARN could not emit refusal reason for #${pr}: ${e?.msg || e?.message || e}`); }
    }
  }
  return { repo, merged, escalated, refused };
}

function arg(argv, n) { const i = argv.indexOf(`--${n}`); return i >= 0 && i + 1 < argv.length ? argv[i + 1] : undefined; }

// Shared CLI entry. Returns a process exit code (does not call process.exit so
// callers can wrap it). TOKEN or GITHUB_TOKEN env supplies the credential.
export async function main(argv, env) {
  const token = env["TOKEN"] || env["GITHUB_TOKEN"];
  const repo = arg(argv, "repo");
  const decisionsFile = arg(argv, "decisions");
  if (!token) { console.error("pr-merge: TOKEN (or GITHUB_TOKEN) env var is required (from credentials['github.token'])"); return 1; }
  if (!repo || !/^[^/]+\/[^/]+$/.test(repo)) { console.error("pr-merge: --repo <owner>/<repo> is required"); return 1; }
  if (!decisionsFile) { console.error("pr-merge: --decisions <file> is required"); return 1; }

  let payload;
  try { payload = JSON.parse(readFileSync(decisionsFile, "utf8")); }
  catch (e) { console.error(`pr-merge: cannot read/parse --decisions "${decisionsFile}": ${e?.message || e}`); return 1; }
  const decisions = Array.isArray(payload?.decisions) ? payload.decisions : null;
  if (!decisions) { console.error("pr-merge: decisions file must be { decisions: [...] }"); return 1; }

  const gh = makeGh({ token, userAgent: "workforce-pr-merge" });
  let result;
  try { result = await applyDecisions(gh, repo, decisions); }
  catch (e) { console.error(`pr-merge: ${e?.msg || e?.message || e}`); return e?.code || 3; }
  console.log(JSON.stringify(result));
  return result.refused > 0 ? 2 : 0;
}

// Run as a CLI when invoked directly (pr-autopilot verdict mode calls this path).
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  process.exit(await main(process.argv, process.env));
}

// @ts-nocheck — the module under test is a dependency-free ESM script, not TS.
// Discovered by workforce/lambdas/vitest.config.mjs (`include:
// ["../skills/**/*-tests.ts"]`), so `cd workforce/lambdas && npm test` runs it.
//
// Locks adr-0023: a 🔴 verdict may return to the author lane ONLY with a brief
// that parses and only while the cycle budget has room for the loop it
// authorises. Both are the difference between "the loop is bounded" and "the
// loop is bounded because the router said so".
import { describe, it, expect } from "vitest";
import {
  BLOCKING_FINDINGS_CODE,
  BRIEF_MARKER,
  assertBriefForCodes,
  briefIsUsable,
  cycleBudgetAllowsAuthorLoop,
  parseRemediationBrief,
} from "./remediation-brief.mjs";

const GOOD = `**Nadia — verdict, cycle 2 of ≤ 7. 🔴 blocking findings.**

\`wf:rafael\` blocked on the swallowed refusal; \`wf:sana\` on the missing case.

**Remediation brief — 2 blocking findings, cycle 2 of ≤ 7.**

1. \`A1\` (\`workforce/skills/pr-autopilot/pr-merge.mjs:88\`) — rethrow the swallowed refusal instead of logging it. Done when: a server-side refusal exits non-zero.
2. \`B2\` (\`workforce/skills/pr-autopilot/pr-merge-tests.ts\`) — cover the refused-decision path. Done when: the suite fails if the rethrow is removed.

— Nadia (CCR persona)
`;

describe("parseRemediationBrief", () => {
  it("parses each item's finding-ID, location, requirement and acceptance clause", () => {
    const b = parseRemediationBrief(GOOD);
    expect(b.present).toBe(true);
    expect(b.problems).toEqual([]);
    expect(b.items.map((i) => i.id)).toEqual(["A1", "B2"]);
    expect(b.items[0].location).toBe("workforce/skills/pr-autopilot/pr-merge.mjs:88");
    expect(b.items[0].requirement).toMatch(/rethrow the swallowed refusal/);
    expect(b.items[0].acceptance).toMatch(/exits non-zero/);
    expect(b.items[1].acceptance).toMatch(/fails if the rethrow is removed/);
  });

  it("accepts a bulleted brief as well as a numbered one", () => {
    const body = "**Remediation brief — 1 finding.**\n\n- `C3` (`a/b.mjs:1`) — add the missing guard. Done when: the guard throws.\n";
    expect(briefIsUsable(body)).toBe(true);
  });

  it("reports an absent brief rather than throwing", () => {
    const b = parseRemediationBrief("**Nadia — verdict, cycle 2 of ≤ 7.** Reviewers had concerns.");
    expect(b.present).toBe(false);
    expect(b.items).toEqual([]);
    expect(b.problems.join(" ")).toMatch(/no \*\*Remediation brief/);
  });

  it("flags an item with no acceptance clause — the next panel could not check it off", () => {
    const body = "**Remediation brief — 1 finding.**\n\n1. `A1` (`a/b.mjs:2`) — fix the thing properly.\n";
    const b = parseRemediationBrief(body);
    expect(b.items).toHaveLength(1);
    expect(b.problems.join(" ")).toMatch(/no "Done when/);
  });

  it("flags an item that restates the complaint instead of naming a change", () => {
    const body = "**Remediation brief — 1 finding.**\n\n1. `A1` (`a/b.mjs:2`) — bad. Done when: good.\n";
    expect(parseRemediationBrief(body).problems.join(" ")).toMatch(/no concrete change/);
  });

  it("flags a heading with no parsable item at all", () => {
    const body = "**Remediation brief — see the reviews above.**\n\nThe reviewers raised several concerns.\n";
    const b = parseRemediationBrief(body);
    expect(b.present).toBe(true);
    expect(b.problems.join(" ")).toMatch(/no parsable finding/);
  });

  it("flags a finding listed twice — one item per finding-ID", () => {
    const body =
      "**Remediation brief — 2 findings.**\n\n" +
      "1. `A1` (`a/b.mjs:2`) — add the missing guard. Done when: it throws.\n" +
      "2. `A1` (`a/c.mjs:9`) — add the missing guard here too. Done when: it throws.\n";
    expect(parseRemediationBrief(body).problems.join(" ")).toMatch(/listed twice/);
  });
});

describe("assertBriefForCodes — the requirement attaches to the 🔴 code only", () => {
  it("throws on a review-findings-blocking hand-off with no brief", () => {
    expect(() => assertBriefForCodes([BLOCKING_FINDINGS_CODE], "reviewers had concerns")).toThrow(/remediation brief/i);
  });

  it("throws on a defective brief, naming the defect", () => {
    const body = "**Remediation brief — 1 finding.**\n\n1. `A1` (`a/b.mjs:2`) — please address the review comment.\n";
    expect(() => assertBriefForCodes([BLOCKING_FINDINGS_CODE], body)).toThrow(/Done when/);
  });

  it("returns the parsed brief when it is usable", () => {
    expect(assertBriefForCodes([BLOCKING_FINDINGS_CODE], GOOD).items).toHaveLength(2);
  });

  it("leaves adr-0022's 🟡 lane untouched — no brief required, no throw", () => {
    expect(assertBriefForCodes(["review-findings-open"], "the author is expected to revise")).toBeNull();
    expect(assertBriefForCodes(["merge-conflict"], "main moved")).toBeNull();
  });
});

describe("cycleBudgetAllowsAuthorLoop — the human gate moved here", () => {
  it("allows a loop that still fits the cap", () => {
    expect(cycleBudgetAllowsAuthorLoop(2, 7).ok).toBe(true);
    expect(cycleBudgetAllowsAuthorLoop(6, 7).ok).toBe(true);
  });

  it("refuses the loop the cap cannot hold, and names the human-lane remedy", () => {
    const v = cycleBudgetAllowsAuthorLoop(7, 7);
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/cycle-cap-exceeded/);
  });

  it("refuses a missing or nonsensical cycle rather than assuming one (C-4)", () => {
    expect(cycleBudgetAllowsAuthorLoop(undefined, 7).ok).toBe(false);
    expect(cycleBudgetAllowsAuthorLoop(0, 7).ok).toBe(false);
    expect(cycleBudgetAllowsAuthorLoop("two", 7).ok).toBe(false);
    expect(cycleBudgetAllowsAuthorLoop(2, "").ok).toBe(false);
  });

  it("honours a binding cycle_cap tighter than the W-4 hard cap", () => {
    expect(cycleBudgetAllowsAuthorLoop(3, 3).ok).toBe(false);
    expect(cycleBudgetAllowsAuthorLoop(2, 3).ok).toBe(true);
  });
});

describe("BRIEF_MARKER", () => {
  it("is the validated-artefact marker, not something the router asserts", () => {
    // The marker means "this parsed"; a body carrying it but no brief is exactly
    // the state the post script must never produce.
    expect(BRIEF_MARKER).toBe("<!-- autopilot:brief -->");
    expect(briefIsUsable(`${BRIEF_MARKER}\n`)).toBe(false);
  });
});

#!/usr/bin/env node
// pr-autopilot/remediation-brief.mjs — the 🔴 → author loop's payload
// (adr-0023, extending adr-0022's author lane).
//
// WHY THIS EXISTS. Under adr-0022 a 🟡 verdict (a reviewer left an open finding)
// goes to the author lane and a 🔴 verdict (a reviewer vetoed) went to a human —
// so a single blocking lens ended the loop, even when the veto named a concrete,
// diff-local defect the `pr-remediate` cadence could have fixed. adr-0023 routes
// that class back to the author instead: the router (the PdM lens) synthesises
// the panel's blocking findings into an ORDERED, ACCEPTANCE-CRITERIA'd brief,
// hands the PR to the author lane with `review-findings-blocking`, and the next
// tick re-reviews at cycle N+1. The human gate moves from "any 🔴" to "the cycle
// budget is spent" (W-4 / the binding's `cycle_cap`).
//
// The brief is the load-bearing artefact of that loop, so it is machine-checked
// rather than merely templated (C-4): a hand-off that says "reviewers had
// concerns" hands the remediation cadence the same ambiguity a human would have
// had to resolve, and the loop then burns its cycle budget on guesses. Every
// item must name WHICH finding, WHERE, WHAT to change, and HOW the next panel
// will know it was done.
//
// Pure + dependency-free so pr-autopilot-post.mjs (the enforcer) and
// pr-remediate-scan.mjs (the consumer) share one definition.

/** The hidden marker a verdict carrying a remediation brief must end up with.
 *  pr-autopilot-post.mjs appends it once the brief validates, so a body that
 *  carries the marker has been through the parser — the marker is a *result*,
 *  never a claim the router can make on its own. */
export const BRIEF_MARKER = "<!-- autopilot:brief -->";

/** The reason code whose hand-off REQUIRES a brief (adr-0023). Kept here beside
 *  the parser so the enforcement site and the taxonomy can't drift. */
export const BLOCKING_FINDINGS_CODE = "review-findings-blocking";

/** The brief section's opening line. Anchors the parse so prose above/below it
 *  (the synthesis, the panel-provenance paragraph, the markers) is ignored. */
const HEADING_RE = /^\s*\*\*Remediation brief[^*]*\*\*\s*$/mu;

// One item, e.g.
//   1. `A1` (`workforce/skills/pr-merge.mjs:88`) — drop the silent catch and
//      rethrow. Done when: the refusal surfaces as a non-zero exit.
// The ID and the location are backticked (never an @-mention, ML-012); the
// requirement is free prose; the acceptance clause is introduced by
// "Done when:" — case-insensitive, anywhere in the item's text.
const ITEM_RE = /^\s*(?:\d+[.)]|[-*])\s+`([A-Za-z]+\d+)`\s*\(`([^`]+)`\)\s*[—\-–:]\s*([\s\S]*?)(?=\n\s*(?:\d+[.)]|[-*])\s+`[A-Za-z]+\d+`|\n\s*\n|$)/gmu;
const ACCEPTANCE_RE = /done when\s*:?\s*(\S[\s\S]*)$/iu;

/**
 * Parse a verdict body's remediation brief.
 *
 * Returns `{ present, items, problems }`:
 *   - `present` — the brief heading was found at all;
 *   - `items`   — `[{ id, location, requirement, acceptance }]`;
 *   - `problems`— human-readable reasons the brief is not usable as-is.
 *
 * Never throws: the caller decides whether a defective brief is fatal (the post
 * script) or merely worth reporting (the remediation scanner reading an older
 * comment written before this contract existed).
 */
export function parseRemediationBrief(body = "") {
  const text = String(body ?? "");
  const h = HEADING_RE.exec(text);
  if (!h) {
    return {
      present: false,
      items: [],
      problems: ["no **Remediation brief …** section found"],
    };
  }
  const section = text.slice(h.index + h[0].length);
  const items = [];
  const problems = [];
  const seen = new Set();
  const re = new RegExp(ITEM_RE.source, "gmu");
  let m;
  while ((m = re.exec(section)) !== null) {
    const id = m[1];
    const location = m[2].trim();
    const raw = m[3].trim().replace(/\s+/g, " ");
    const acc = ACCEPTANCE_RE.exec(raw);
    const requirement = (acc ? raw.slice(0, acc.index) : raw).trim().replace(/[—\-–,;:]\s*$/u, "");
    const acceptance = acc ? acc[1].trim() : "";
    if (seen.has(id)) problems.push(`finding \`${id}\` is listed twice — one item per finding-ID`);
    seen.add(id);
    if (!acceptance) {
      problems.push(`item \`${id}\` has no "Done when: …" acceptance clause — the next panel must be able to check it off`);
    }
    if (requirement.length < 12) {
      problems.push(`item \`${id}\` states no concrete change ("${requirement}") — name what to do, not that something is wrong`);
    }
    items.push({ id, location, requirement, acceptance });
  }
  if (items.length === 0) {
    problems.push(
      'the brief lists no parsable finding — each item is "1. `A1` (`path/to/file:line`) — <change>. Done when: <acceptance>."',
    );
  }
  return { present: true, items, problems };
}

/** True when the body carries a brief this contract accepts. */
export function briefIsUsable(body = "") {
  const b = parseRemediationBrief(body);
  return b.present && b.problems.length === 0;
}

/**
 * The C-4 gate at the hand-off site (adr-0023). Throws unless the body carries
 * a usable brief. `codes` is the resolved reason-code set: the requirement
 * attaches to `review-findings-blocking` only, so adr-0022's 🟡 lane
 * (`review-findings-open`, whose findings already sit verbatim in the thread)
 * keeps working unchanged and no running SKILL body breaks on this landing.
 */
export function assertBriefForCodes(codes = [], body = "") {
  if (!codes.includes(BLOCKING_FINDINGS_CODE)) return null;
  const brief = parseRemediationBrief(body);
  if (!brief.present || brief.problems.length > 0) {
    throw new Error(
      `--reason ${BLOCKING_FINDINGS_CODE} requires a machine-checkable remediation brief in the verdict body ` +
        `(adr-0023): ${brief.problems.join("; ")}. A 🔴 handed to the author lane is only as good as the brief ` +
        `it carries — the remediation cadence cannot re-derive a panel's blocking findings from "concerns were raised".`,
    );
  }
  return brief;
}

/**
 * The loop's bound (adr-0023). The 🔴 → author → re-review loop is bounded by
 * the SAME cycle budget the review loop always had: hand a PR back to the author
 * only while a further cycle may legitimately run. At or past the cap, the
 * decision is a human's and the code is `cycle-cap-exceeded`.
 *
 * `cycle` is the cycle this verdict closes; the loop it authorises is `cycle+1`.
 * Returns `{ ok, why }` rather than throwing — the caller renders the refusal.
 */
export function cycleBudgetAllowsAuthorLoop(cycle, cap) {
  const n = Number(cycle);
  const c = Number(cap);
  if (!Number.isFinite(n) || n < 1) return { ok: false, why: `--cycle must be a positive integer (got "${cycle}")` };
  if (!Number.isFinite(c) || c < 1) return { ok: false, why: `--cycle-cap must be a positive integer (got "${cap}")` };
  if (n + 1 > c) {
    return {
      ok: false,
      why:
        `this verdict closes cycle ${n} of ≤ ${c}, so the loop it would authorise (cycle ${n + 1}) is past the cap — ` +
        `the author lane may not extend a review loop beyond its budget. Post as ` +
        `--needs-human --reason cycle-cap-exceeded (adr-0023).`,
    };
  }
  return { ok: true, why: `cycle ${n + 1} of ≤ ${c} remains within the budget` };
}

#!/usr/bin/env node
// pr-remediate/pr-remediate-post.mjs — the AUTHOR lane's only write surface for
// GitHub metadata (adr-0022).
//
// The remediation cadence's real work lands as commits on the PR's HEAD branch
// (R-N9: never the default branch). This script writes the *record* of that
// work and moves the PR out of the lane, in exactly three shapes:
//
//   --claim      FIRST, before any work. Posts the attempt marker
//                `<!-- autopilot:remediation:<n> -->` and nothing else — the
//                lane's bound is counted from these, so the attempt must be
//                spent before it can fail. Without this ordering the cap is
//                enforced by the cadence it bounds (`wf:farah` F1 on #518): a
//                session that dies after pushing but before recording would
//                refresh the PR's updated_at — resetting the sweep's staleness
//                clock — while consuming no attempt, and could retry the same
//                failing resolution forever. Same once-ever-latch idiom as
//                flaky-rerun.mjs. Refuses to re-claim an attempt already
//                claimed, so a re-run of the same fire cannot double-spend.
//
//   --resolved   an attempt was made and pushed. Posts the outcome comment
//                (stamped with `<!-- autopilot:remediation:<n> -->`, the marker
//                the lane's bound is counted from), REMOVES
//                `autopilot:needs-author` and the author-lane reason labels, and
//                leaves the PR to pr-autopilot's next tick — whose scan sees a
//                head commit newer than the last routing comment and re-routes
//                it at cycle N+1. That re-route, not this script, is what
//                decides whether the fix was any good.
//
//   --blocked    the attempt cannot be made or cannot be finished. Posts the
//                hand-off (needs-human marker + reason marker + attempt marker),
//                stamps `autopilot:needs-human` + the reason label, and removes
//                the author label. The PR leaves the agent lane for the human
//                one; it is never left in both.
//
// It has no code path that approves, merges, or pushes — the same R-N9 / W-5
// posture as pr-autopilot-post.mjs, whose guards (raw @-mention refusal ML-012,
// the reason requirement) are imported rather than re-implemented so the two
// write surfaces cannot drift.
//
// Usage:
//   GITHUB_TOKEN=… node workforce/skills/pr-remediate/pr-remediate-post.mjs \
//     --project agent-workforce --pr 517 --attempt 1 \
//     --body-file /tmp/remediation-517.md \
//     ( --claim | --resolved | --blocked --reason remediation-blocked [--reason-text "…"] )
//
// --claim needs no --body-file (the marker IS the record); the other two do.
//
// Exit codes: 0 posted · 1 bad args / refused guard · 2 endpoint rejected ·
//             3 network / unexpected.

import { ensureProxyAwareEntry } from "../../../scripts/lib/proxy-bootstrap.mjs"
ensureProxyAwareEntry(import.meta.url)

import { readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";
import { projectRepo } from "../pr-autopilot/pr-autopilot-scan.mjs";
import {
  AUTHOR_LABEL,
  ESCALATION_LABEL,
  REMEDIATION_CAP,
  countRemediationAttempts,
  ensureLabels,
  makeGh,
  remediationMarker,
} from "../pr-autopilot/pr-merge.mjs";
import { findRawMentions, NEEDS_HUMAN_MARKER } from "../pr-autopilot/pr-autopilot-post.mjs";
import { AUTHOR_LANE_CODES, assertReasonCode, isAuthorLaneCode, reasonLabel, reasonMarker } from "../pr-autopilot/escalation-reasons.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");

/** Labels a resolved attempt clears from the PR. The author label itself, plus
 *  the author-lane reason labels — a stale `autopilot:reason:merge-conflict`
 *  sitting on a PR whose conflict is resolved is a lie the funnel would read as
 *  fact, and the next verdict re-stamps whatever is still true. Human-lane
 *  reason labels are never touched here: this script may not un-escalate. */
export function labelsToClearOnResolve(labels = []) {
  const authorReasonLabels = AUTHOR_LANE_CODES.map(reasonLabel);
  return labels
    .map((l) => String(l || ""))
    .filter((l) => l === AUTHOR_LABEL || authorReasonLabels.includes(l));
}

/** The claim comment. Deliberately minimal: it exists to spend the attempt
 *  before the work, so it must not depend on anything the work produces. */
export function claimBody(attempt, cap = REMEDIATION_CAP) {
  return [
    `**Remediation attempt ${attempt} of ≤ ${cap} — claimed.**`,
    "",
    "Starting work on this PR's author-lane blocker. This attempt is spent from here on: " +
      "if this run dies before recording an outcome, the attempt still counts (adr-0022 / `wf:farah` F1 — " +
      "a cap the bounded cadence increments only on success is not a cap). The outcome comment follows.",
    "",
    "— pr-remediate (see workforce/skills/pr-remediate/SKILL.md)",
    "",
    remediationMarker(attempt),
  ].join("\n");
}

/** A `--blocked` hand-off leaves the agent lane, so its reason must be one no
 *  agent is expected to clear. Refusing an author-lane code here is what stops
 *  the loop "escalate → re-park → escalate" from forming. */
export function assertBlockedReason(code) {
  assertReasonCode(code);
  if (isAuthorLaneCode(code)) {
    throw new Error(
      `--blocked cannot carry the author-lane reason "${code}" — that code means "an agent can fix this", ` +
        `which is the state we are leaving. Use remediation-blocked (a resolution only a human should make), ` +
        `remediation-cap-exceeded (attempts spent), or the specific human-lane clause (adr-0022).`,
    );
  }
  return code;
}

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}
const flag = (name) => process.argv.includes(`--${name}`);

async function main() {
  const token = process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
  const projectId = arg("project");
  const prNumber = arg("pr");
  const bodyFile = arg("body-file");
  const attempt = Number(arg("attempt"));
  const claim = flag("claim");
  const resolved = flag("resolved");
  const blocked = flag("blocked");
  let repo = arg("repo");

  if (!token) return die(2, "GITHUB_TOKEN (or GH_TOKEN) env is required");
  if (!prNumber || !/^\d+$/.test(prNumber)) return die(1, "--pr <number> is required (positive integer)");
  const modes = [claim, resolved, blocked].filter(Boolean).length;
  if (modes !== 1) {
    return die(1, "pass exactly one of --claim / --resolved / --blocked — an attempt is claimed before the work, then recorded as one outcome");
  }
  if (!claim && !bodyFile) return die(1, "--body-file <path> is required for --resolved / --blocked");
  if (!repo && projectId) {
    try {
      const r = projectRepo(REPO_ROOT, projectId);
      repo = `${r.owner}/${r.repo}`;
    } catch (e) {
      return die(1, e.message);
    }
  }
  if (!repo || !/^[^/]+\/[^/]+$/.test(repo)) return die(1, "--repo <owner>/<repo> (or --project <id>) is required");

  let marker;
  try {
    marker = remediationMarker(attempt);
  } catch (e) {
    return die(1, `--attempt <n>: ${e instanceof Error ? e.message : String(e)}`);
  }

  let body;
  if (claim) {
    body = claimBody(attempt);
  } else {
    try {
      body = readFileSync(bodyFile, "utf8");
    } catch {
      return die(1, `body-file unreadable: ${bodyFile}`);
    }
    if (body.trim().length === 0) return die(1, "body-file is empty — refusing to post an empty remediation record (W-4)");
  }

  // ML-012, imported from the sibling write surface: persona slugs are not
  // GitHub accounts and a raw @ notifies the real user who owns that name.
  const mentions = findRawMentions(body);
  if (mentions.length > 0) {
    return die(1, `body contains raw GitHub @-mention(s): ${mentions.join(", ")} — reference agents as \`wf:<slug>\` (ML-012)`);
  }

  // The outcome comments carry the marker too — harmless (the counter reads the
  // MAXIMUM attempt number, not a tally), and it keeps each outcome legible
  // beside the attempt it belongs to.
  if (!body.includes(marker)) body = `${body.trimEnd()}\n\n${marker}\n`;

  const labelsToAdd = [];
  let reasonCode;
  if (blocked) {
    reasonCode = arg("reason");
    if (!reasonCode) return die(1, "--blocked requires --reason <code> (adr-0022 / Epic-019: every hand-off says why)");
    try {
      assertBlockedReason(reasonCode);
      const rm = reasonMarker(reasonCode, arg("reason-text") ?? "");
      if (!body.includes(`autopilot:reason:${reasonCode}`)) body = `${body.trimEnd()}\n\n${rm}\n`;
    } catch (e) {
      return die(1, e instanceof Error ? e.message : String(e));
    }
    if (!body.includes(NEEDS_HUMAN_MARKER)) body = `${body.trimEnd()}\n\n${NEEDS_HUMAN_MARKER}\n`;
    labelsToAdd.push(ESCALATION_LABEL, reasonLabel(reasonCode));
  }

  const gh = makeGh({ token, userAgent: "workforce-pr-remediate" });

  let current = [];
  let alreadyClaimed = 0;
  try {
    const [p, cs] = await Promise.all([
      gh("GET", `/repos/${repo}/pulls/${prNumber}`),
      gh("GET", `/repos/${repo}/issues/${prNumber}/comments?per_page=100`),
    ]);
    if (p.status !== 200) return die(3, `GET pull ${prNumber} -> HTTP ${p.status}`);
    current = Array.isArray(p.json?.labels) ? p.json.labels.map((l) => l?.name) : [];
    alreadyClaimed = countRemediationAttempts(Array.isArray(cs.json) ? cs.json.map((x) => x.body) : []);
  } catch (e) {
    return die(3, e?.msg || e?.message || String(e));
  }

  // A claim must be strictly the next attempt. Re-claiming one already spent
  // would let a re-run of the same fire double-spend the budget in the loose
  // direction (two claims, one increment); claiming past the cap is the lane's
  // exit, not another try. Both refuse rather than guess (C-4).
  if (claim) {
    if (alreadyClaimed >= REMEDIATION_CAP) {
      return die(1, `all ${REMEDIATION_CAP} attempts on #${prNumber} are already claimed — escalate with --blocked --reason remediation-cap-exceeded (adr-0022)`);
    }
    if (attempt !== alreadyClaimed + 1) {
      return die(1, `--attempt ${attempt} does not follow the ${alreadyClaimed} attempt(s) already claimed on #${prNumber} — claim attempt ${alreadyClaimed + 1}`);
    }
  }

  // Comment first: the record must exist before the labels move, so a failure
  // half-way leaves the PR in the lane WITH its evidence rather than out of the
  // lane with none (the direction that keeps the sweep able to catch it).
  let c;
  try {
    c = await gh("POST", `/repos/${repo}/issues/${prNumber}/comments`, { body });
  } catch (e) {
    return die(3, e?.msg || e?.message || String(e));
  }
  if (c.status !== 201) return die(c.status < 500 ? 2 : 3, `POST comment -> HTTP ${c.status}`);
  const mode = claim ? "claimed" : blocked ? "blocked" : "resolved";
  console.error(`pr-remediate-post: attempt ${attempt}/${REMEDIATION_CAP} on ${repo}#${prNumber} (${mode})`);

  // A claim only spends the attempt. The PR stays exactly where it is — in the
  // lane, with its labels — because the work has not happened yet and the sweep
  // must still be able to catch this run if it dies.
  if (claim) return 0;

  if (labelsToAdd.length > 0) {
    await ensureLabels(gh, repo, labelsToAdd);
    const l = await gh("POST", `/repos/${repo}/issues/${prNumber}/labels`, { labels: labelsToAdd });
    if (l.status !== 200) console.error(`pr-remediate-post: WARN could not label #${prNumber} -> HTTP ${l.status}`);
  }

  // Both shapes leave the author lane. Best-effort per label (404 = already
  // gone); a failure here is loud in the log but must not undo a landed record.
  for (const name of labelsToClearOnResolve(current)) {
    const d = await gh("DELETE", `/repos/${repo}/issues/${prNumber}/labels/${encodeURIComponent(name)}`);
    if (d.status !== 200 && d.status !== 404) console.error(`pr-remediate-post: WARN could not clear "${name}" -> HTTP ${d.status}`);
  }

  return 0;
}

function die(code, msg) {
  console.error(`pr-remediate-post: ${msg}`);
  return code;
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  process.exit(await main().catch((e) => die(3, e instanceof Error ? e.message : String(e))));
}

// @ts-nocheck — the scripts under test (pr-remediate-*.mjs) are dependency-free
// ESM scripts, not TS; vitest/esbuild imports them fine at runtime, and this
// suite is not shipped code. Discovered by workforce/lambdas/vitest.config.mjs
// (`include: ["../skills/**/*-tests.ts"]`).
//
// Locks the AUTHOR lane's decision surface (adr-0022). Two properties matter
// more than any individual case:
//   1. the cadence never touches a PR that is not its own (not-in-lane /
//      terminal / paused), and
//   2. the lane is BOUNDED — the attempt cap is checked before any work is
//      classified as actionable, and an unclassifiable PR escalates rather than
//      sitting in the queue forever.
import { describe, it, expect } from "vitest";
import { classifyRemediation, latestBrief, reasonCodesFrom } from "./pr-remediate-scan.mjs";
import { labelsToClearOnResolve, assertBlockedReason, claimBody } from "./pr-remediate-post.mjs";
import { AUTHOR_LABEL, ESCALATION_LABEL, REMEDIATION_CAP, countRemediationAttempts } from "../pr-autopilot/pr-merge.mjs";

const inLane = (over = {}) => ({ labels: [AUTHOR_LABEL], mergeable: true, mergeableState: "clean", reasons: [], attempts: 0, ...over });

describe("classifyRemediation — whose PR is this?", () => {
  it("a PR without the author label is never touched", () => {
    expect(classifyRemediation({ labels: [], mergeableState: "dirty" })).toMatchObject({ kind: "not-in-lane", actionable: false });
  });

  it("the human lane wins when both labels are present — a human owns it", () => {
    const v = classifyRemediation(inLane({ labels: [AUTHOR_LABEL, ESCALATION_LABEL], mergeableState: "dirty" }));
    expect(v).toMatchObject({ kind: "terminal", actionable: false });
  });

  it("autopilot:off pauses this cadence too", () => {
    expect(classifyRemediation(inLane({ labels: [AUTHOR_LABEL, "autopilot:off"], mergeableState: "dirty" }))).toMatchObject({
      kind: "not-in-lane",
    });
  });
});

describe("classifyRemediation — the bound comes before the work", () => {
  it("a PR at the cap escalates, even with a plainly fixable conflict", () => {
    const v = classifyRemediation(inLane({ mergeableState: "dirty", attempts: REMEDIATION_CAP }));
    expect(v).toMatchObject({ kind: "cap-exceeded", actionable: false, escalate: "remediation-cap-exceeded" });
  });

  it("one attempt below the cap is still actionable", () => {
    expect(classifyRemediation(inLane({ mergeableState: "dirty", attempts: REMEDIATION_CAP - 1 }))).toMatchObject({
      kind: "merge-conflict",
      actionable: true,
    });
  });
});

describe("classifyRemediation — kind ordering", () => {
  it("a conflict outranks findings and checks: the tree they describe will not survive the merge", () => {
    const v = classifyRemediation(inLane({ mergeableState: "dirty", reasons: ["review-findings-open", "checks-failing"] }));
    expect(v.kind).toBe("merge-conflict");
  });

  it("mergeable=false alone (state not yet computed) is still a conflict", () => {
    expect(classifyRemediation(inLane({ mergeable: false, mergeableState: "" })).kind).toBe("merge-conflict");
  });

  it("behind is its own, weaker case", () => {
    expect(classifyRemediation(inLane({ mergeableState: "behind" })).kind).toBe("branch-behind");
  });

  it("a stated finding outranks a red check", () => {
    const v = classifyRemediation(inLane({ reasons: ["checks-failing", "review-findings-open"] }));
    expect(v.kind).toBe("review-findings");
  });

  it("adr-0023: a briefed 🔴 is the same work-kind, flagged blocking, and outranks the 🟡 code", () => {
    const v = classifyRemediation(inLane({ reasons: ["review-findings-open", "review-findings-blocking"] }));
    expect(v).toMatchObject({ kind: "review-findings", blocking: true, actionable: true });
    expect(v.why).toMatch(/VETOED/);
  });

  it("a conflict still outranks a briefed 🔴", () => {
    expect(classifyRemediation(inLane({ mergeableState: "dirty", reasons: ["review-findings-blocking"] })).kind).toBe(
      "merge-conflict",
    );
  });

  it("a red check alone is actionable", () => {
    expect(classifyRemediation(inLane({ reasons: ["checks-failing"] })).kind).toBe("checks-failing");
  });
});

describe("classifyRemediation — an unclassifiable PR escalates, never idles", () => {
  it("parked in the lane, clean, no reason codes -> unclear + escalate", () => {
    const v = classifyRemediation(inLane());
    expect(v).toMatchObject({ kind: "unclear", actionable: false, escalate: "remediation-blocked" });
  });
});

describe("reasonCodesFrom — the hand-off's own words", () => {
  it("collects codes across bodies, de-duplicated and order-preserving", () => {
    const bodies = [
      "verdict <!-- autopilot:reason:merge-conflict -->",
      "sweep <!-- autopilot:reason:merge-conflict --> <!-- autopilot:reason:review-findings-open -->",
    ];
    expect(reasonCodesFrom(bodies)).toEqual(["merge-conflict", "review-findings-open"]);
  });

  it("an unknown code throws (C-4) rather than being read as a new bucket", () => {
    expect(() => reasonCodesFrom(["<!-- autopilot:reason:made-up -->"])).toThrow(/unknown/);
  });
});

describe("pr-remediate-post — leaving the lane cleanly", () => {
  it("a resolved attempt clears the author label and its stale author-lane reasons only", () => {
    const cleared = labelsToClearOnResolve([
      AUTHOR_LABEL,
      "autopilot:reason:merge-conflict",
      "autopilot:reason:l0l1-path",
      "type:chore",
    ]);
    expect(cleared).toEqual([AUTHOR_LABEL, "autopilot:reason:merge-conflict"]);
  });

  it("a blocked hand-off cannot carry an author-lane reason — that is the state being left", () => {
    expect(() => assertBlockedReason("merge-conflict")).toThrow(/cannot carry the author-lane reason/);
    expect(() => assertBlockedReason("review-findings-open")).toThrow(/cannot carry the author-lane reason/);
  });

  it("the two exit reasons and specific human-lane clauses are accepted", () => {
    for (const code of ["remediation-blocked", "remediation-cap-exceeded", "l0l1-path"]) {
      expect(() => assertBlockedReason(code)).not.toThrow();
    }
  });

  it("an unknown blocked reason throws", () => {
    expect(() => assertBlockedReason("gave-up")).toThrow(/unknown/);
  });
});

// wf:farah F1 on #518: a cap the bounded cadence increments only on success is
// not a cap. The claim comment is what spends the attempt BEFORE the work, so a
// run that dies mid-attempt cannot refund itself — these lock that the claim
// carries the counter and nothing that depends on the work having succeeded.
describe("claimBody — the attempt is spent before the work", () => {
  it("carries the attempt marker the cap is counted from", () => {
    expect(claimBody(2)).toContain("<!-- autopilot:remediation:2 -->");
  });

  it("is round-trippable by the counter", () => {
    expect(countRemediationAttempts([claimBody(1), claimBody(2)])).toBe(2);
  });

  it("claims nothing about an outcome — it is posted before there is one", () => {
    const body = claimBody(1).toLowerCase();
    for (const word of ["resolved", "fixed", "pushed to", "verified"]) expect(body).not.toContain(word);
  });

  it("refuses to render an attempt past the cap", () => {
    expect(() => claimBody(REMEDIATION_CAP + 1)).toThrow(/remediation-cap-exceeded/);
  });
});

describe("latestBrief — the 🔴 loop's work-list (adr-0023)", () => {
  const brief = (id: string, text: string) =>
    `**Remediation brief — 1 blocking finding.**\n\n1. \`${id}\` (\`a/b.mjs:2\`) — ${text}. Done when: the guard throws.\n\n<!-- autopilot:brief -->\n`;

  it("returns null when no comment carries a brief (the 🟡 lane has none by construction)", () => {
    expect(latestBrief(["**Nadia — verdict, cycle 1.** revise please"])).toBeNull();
  });

  it("returns the NEWEST brief — an earlier cycle describes a tree that no longer exists", () => {
    const got = latestBrief([brief("A1", "add the first guard"), "unrelated", brief("B2", "add the second guard")]);
    expect(got.items.map((i) => i.id)).toEqual(["B2"]);
  });

  it("skips a marked-but-unparsable body rather than half-consuming it", () => {
    expect(latestBrief(["**Remediation brief — see above.**\n\nconcerns.\n\n<!-- autopilot:brief -->\n"])).toBeNull();
  });
});

#!/usr/bin/env node
// pr-remediate/pr-remediate-scan.mjs — deterministic discovery for the AUTHOR
// lane (adr-0022).
//
// pr-autopilot ends every PR it touches in one of two terminal states, and
// hands the agent-fixable middle to the author lane (`autopilot:needs-author`).
// This script is that lane's read-only scanner: it lists every PR sitting in it,
// classifies WHAT is wrong (conflict / behind / failing checks / open review
// findings), counts how many remediation attempts the PR has already spent, and
// writes the whole candidate — diff-relevant PR fields, the hand-off reasons,
// the reviewer findings — to a JSON file the session then works from.
//
// Read-only by construction: GET only. Every write in this cadence goes through
// git (the head branch, per R-N9 — never the default branch) or through
// pr-remediate-post.mjs. Nothing here approves, merges, or comments.
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node workforce/skills/pr-remediate/pr-remediate-scan.mjs \
//       --project agent-workforce [--repo owner/repo] \
//       [--max 3] [--out /tmp/pr-remediate-candidates.json] [--json]
//
// Exit codes: 0 ok (including "0 candidates" — a cheap, normal outcome)
//             1 bad args · 3 network / unexpected.

import { ensureProxyAwareEntry } from "../../../scripts/lib/proxy-bootstrap.mjs"
ensureProxyAwareEntry(import.meta.url)

import { writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";
import { projectRepo } from "../pr-autopilot/pr-autopilot-scan.mjs";
import {
  AUTHOR_LABEL,
  ESCALATION_LABEL,
  REMEDIATION_CAP,
  countRemediationAttempts,
  makeGh,
} from "../pr-autopilot/pr-merge.mjs";
import { findReasonMarkers } from "../pr-autopilot/escalation-reasons.mjs";
import { BRIEF_MARKER, parseRemediationBrief } from "../pr-autopilot/remediation-brief.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");
const AUTOPILOT_OFF_LABEL = "autopilot:off";

export const DEFAULT_MAX = 3;

/**
 * The pure decision: given one PR's state, what (if anything) should the
 * remediation cadence do about it?
 *
 * Ordering is load-bearing, not cosmetic:
 *   1. `not-in-lane` / `terminal` — never touch a PR that isn't ours. The human
 *      lane wins over the author lane whenever both labels are somehow present:
 *      a PR a human owns is not one an agent may keep pushing to.
 *   2. `cap-exceeded` — the bound comes before the work. A PR that has spent its
 *      attempts is escalated, never given "just one more" try.
 *   3. `merge-conflict` — before everything else fixable, because until the
 *      branch merges the base cleanly, no check result and no review finding on
 *      it can be trusted: they describe a tree that will not exist after the
 *      resolution.
 *   4. `branch-behind` — same reasoning, weaker form.
 *   5. `review-findings` before `checks-failing` — a lens finding is a stated
 *      defect with a named fix; a red check is a symptom, and fixing the stated
 *      defect frequently clears it.
 *   6. `unclear` — parked in the lane with no recognisable cause. NOT a no-op:
 *      the caller escalates it (`remediation-blocked`), because a PR nobody can
 *      classify is exactly what the lane must not silently accumulate (C-4).
 */
export function classifyRemediation({
  labels = [],
  mergeable,
  mergeableState = "",
  reasons = [],
  attempts = 0,
  cap = REMEDIATION_CAP,
} = {}) {
  const names = labels.map((l) => String(l || "").toLowerCase());
  const state = String(mergeableState || "").toLowerCase();
  const codes = new Set(reasons);

  if (names.includes(AUTOPILOT_OFF_LABEL)) return { kind: "not-in-lane", actionable: false, why: "autopilot:off — maintainer pause" };
  if (names.includes(ESCALATION_LABEL)) return { kind: "terminal", actionable: false, why: `${ESCALATION_LABEL} — a human owns this PR` };
  if (!names.includes(AUTHOR_LABEL)) return { kind: "not-in-lane", actionable: false, why: `no ${AUTHOR_LABEL} label` };

  if (attempts >= cap) {
    return {
      kind: "cap-exceeded",
      actionable: false,
      escalate: "remediation-cap-exceeded",
      why: `${attempts} of ${cap} remediation attempts spent — the lane is exhausted, escalate to a human`,
    };
  }

  if (state === "dirty" || mergeable === false) {
    return { kind: "merge-conflict", actionable: true, why: `head conflicts with the base (mergeable=${mergeable}, state=${state || "?"})` };
  }
  if (state === "behind") {
    return { kind: "branch-behind", actionable: true, why: "head is out of date with the base branch" };
  }
  // adr-0023 first: a 🔴 veto routed back here carries an ORDERED remediation
  // brief (validated at the hand-off), so it is the better-specified of the two
  // findings kinds and the session should work it from the brief, not from a
  // re-read of every review body. Same `review-findings` kind — the work is the
  // same shape — with the blocking flag so the outcome comment can say which
  // loop it closed.
  if (codes.has("review-findings-blocking")) {
    return {
      kind: "review-findings",
      blocking: true,
      actionable: true,
      why: "a lens VETOED (🔴) and the router organised the blocking findings into a remediation brief (adr-0023)",
    };
  }
  if (codes.has("review-findings-open")) {
    return { kind: "review-findings", blocking: false, actionable: true, why: "one or more lens reviews left an open blocking finding" };
  }
  if (codes.has("checks-failing")) {
    return { kind: "checks-failing", actionable: true, why: "a required check completed non-green" };
  }
  return {
    kind: "unclear",
    actionable: false,
    escalate: "remediation-blocked",
    why: `parked in the author lane with no recognisable fixable cause (state=${state || "?"}, reasons=[${[...codes].join(", ") || "none"}])`,
  };
}

/** The newest usable remediation brief among the PR's comment/review bodies
 *  (adr-0023), as `{ items, body }` — or `null` when none carries one. Newest
 *  wins: a re-routed PR accumulates one brief per 🔴 cycle, and only the last
 *  one describes the tree the session is about to fix. A brief that no longer
 *  parses (hand-written, or predating the contract) is skipped rather than
 *  half-consumed — the review bodies remain the fallback source. */
export function latestBrief(bodies = []) {
  for (let i = bodies.length - 1; i >= 0; i--) {
    const body = String(bodies[i] ?? "");
    if (!body.includes(BRIEF_MARKER)) continue;
    const parsed = parseRemediationBrief(body);
    if (parsed.present && parsed.problems.length === 0) return { items: parsed.items, body };
  }
  return null;
}

/** Reason codes carried by the PR's hand-off comments, de-duplicated, newest
 *  comment last. Unknown codes throw (C-4) via findReasonMarkers. */
export function reasonCodesFrom(bodies = []) {
  const codes = [];
  for (const b of bodies) for (const { code } of findReasonMarkers(b)) if (!codes.includes(code)) codes.push(code);
  return codes;
}

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : fallback;
}

async function main() {
  const token = process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
  const projectId = arg("project");
  const out = arg("out");
  const asJson = process.argv.includes("--json");
  const max = Number(arg("max", String(DEFAULT_MAX)));
  let repo = arg("repo");

  if (!token) return die(1, "GITHUB_TOKEN (or GH_TOKEN) env is required (from credentials['github.token'].token)");
  if (!repo && projectId) {
    try {
      const r = projectRepo(REPO_ROOT, projectId);
      repo = `${r.owner}/${r.repo}`;
    } catch (e) {
      return die(1, e.message);
    }
  }
  if (!repo || !/^[^/]+\/[^/]+$/.test(repo)) return die(1, "--repo <owner>/<repo> (or --project <id>) is required");
  if (!Number.isFinite(max) || max <= 0) return die(1, `--max must be positive (got ${max})`);

  const gh = makeGh({ token, userAgent: "workforce-pr-remediate" });

  // Search is the cheap filter: only PRs already in the lane are candidates.
  let numbers;
  try {
    const q = encodeURIComponent(`repo:${repo} is:pr is:open label:"${AUTHOR_LABEL}"`);
    const r = await gh("GET", `/search/issues?q=${q}&per_page=100`);
    if (r.status !== 200 || !Array.isArray(r.json?.items)) return die(3, `search -> HTTP ${r.status}`);
    numbers = r.json.items.map((it) => it.number);
  } catch (e) {
    return die(3, e?.msg || e?.message || String(e));
  }

  const candidates = [];
  for (const number of numbers) {
    if (candidates.length >= max) break;
    let pr, bodies, reviews, checks;
    try {
      // The PR detail is fetched singly (not from search) because `mergeable` /
      // `mergeable_state` are only computed on the individual-PR endpoint, and
      // they are the whole point of this scan.
      const [p, c, rv] = await Promise.all([
        gh("GET", `/repos/${repo}/pulls/${number}`),
        gh("GET", `/repos/${repo}/issues/${number}/comments?per_page=100`),
        gh("GET", `/repos/${repo}/pulls/${number}/reviews?per_page=100`),
      ]);
      if (p.status !== 200) return die(3, `GET pull ${number} -> HTTP ${p.status}`);
      pr = p.json;
      reviews = Array.isArray(rv.json) ? rv.json : [];
      bodies = [
        ...(Array.isArray(c.json) ? c.json.map((x) => x.body) : []),
        ...reviews.map((x) => x.body),
      ];
      const cr = await gh("GET", `/repos/${repo}/commits/${pr.head?.sha}/check-runs?per_page=100`);
      checks = Array.isArray(cr.json?.check_runs)
        ? cr.json.check_runs.map((x) => ({ name: x.name, status: x.status, conclusion: x.conclusion }))
        : [];
    } catch (e) {
      return die(3, `#${number}: ${e?.msg || e?.message || String(e)}`);
    }

    const labels = Array.isArray(pr.labels) ? pr.labels.map((l) => l?.name) : [];
    const attempts = countRemediationAttempts(bodies);
    const reasons = reasonCodesFrom(bodies);
    const verdict = classifyRemediation({
      labels,
      mergeable: pr.mergeable,
      mergeableState: pr.mergeable_state,
      reasons,
      attempts,
    });

    candidates.push({
      number,
      title: pr.title,
      url: pr.html_url,
      draft: pr.draft === true,
      head: { ref: pr.head?.ref, sha: pr.head?.sha },
      base: { ref: pr.base?.ref },
      mergeable: pr.mergeable,
      mergeable_state: pr.mergeable_state,
      labels,
      attempts,
      attempt_next: attempts + 1,
      attempts_left: Math.max(0, REMEDIATION_CAP - attempts),
      reasons,
      checks,
      failing_checks: checks.filter((c) => c.status === "completed" && c.conclusion !== "success" && c.conclusion !== "neutral" && c.conclusion !== "skipped"),
      // Verbatim, un-summarised: the session needs the reviewers' own words to
      // address a finding by its finding-ID, and a scanner's paraphrase is
      // exactly how a finding gets "addressed" without being fixed.
      review_bodies: reviews.map((r) => ({ state: r.state, body: r.body })),
      // adr-0023: the newest usable remediation brief, parsed into items. It is
      // the router's ORDERED synthesis of the panel's blocking findings, with an
      // acceptance clause per item — the work-list for a `review-findings`
      // (blocking) run. `null` when the PR arrived via the 🟡 lane, which has no
      // brief by construction; then the review bodies above are the source.
      remediation_brief: latestBrief(bodies),
      remediation: verdict,
    });
  }

  const payload = { repo, cap: REMEDIATION_CAP, scanned: numbers.length, candidates };
  if (out) {
    writeFileSync(out, JSON.stringify(payload, null, 2));
    console.error(`pr-remediate-scan: ${candidates.length} candidate(s) of ${numbers.length} in the lane -> ${out}`);
  }
  if (asJson || !out) console.log(JSON.stringify(payload, null, 2));
  for (const c of candidates) {
    console.error(`  - #${c.number} [${c.remediation.kind}] attempt ${c.attempt_next}/${REMEDIATION_CAP} — ${c.remediation.why}`);
  }
  return 0;
}

function die(code, msg) {
  console.error(`pr-remediate-scan: ${msg}`);
  return code;
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  process.exit(await main().catch((e) => die(3, e instanceof Error ? e.message : String(e))));
}

#!/usr/bin/env node
// reader-signal/post.mjs — deterministic write for the "reader-signal" Cadence,
// invoked by the CCR agent-runner AFTER it has *generated* the content. The LLM
// owns the judgment (body / structured fields); this script owns the
// structurally-exact write so the failure class "LLM hand-edits JSON and
// guesses the schema wrong" cannot recur. Modeled on
// workforce/skills/feed-post/post-feed.mjs — the canonical Cadence write.
//
// It POSTs to an authenticated endpoint with the project-scoped credential
// injected per-fire (credentials['workforce.feed_write_token']). The script does NOT
// touch the repo, does NOT open a PR — the write lands directly in the backing
// store. No human approval gate.
//
// Body is read from a FILE (not an arg) so multi-line / Unicode prose can't be
// mangled by shell quoting. The write CREDENTIAL is injected per-fire; the
// endpoint URL is NOT a secret and is the single source of truth right here.
//
// Usage:
//   FEED_WRITE_TOKEN=<from credentials['workforce.feed_write_token']> \
//     node workforce/skills/reader-signal/post.mjs \
//       --agent <slug> --body-file /tmp/body.md [--skill-version 0.1.0]
//
// Exit codes:
//   0  — written (HTTP 2xx)
//   1  — bad args / env / body-file unreadable
//   2  — endpoint rejected (HTTP 401 auth / 422 validation)
//   3  — network / unexpected error

import { ensureProxyAwareEntry } from "../../../scripts/lib/proxy-bootstrap.mjs";
ensureProxyAwareEntry(import.meta.url);

import { readFileSync } from "node:fs";

// Single source of truth for this Cadence's write endpoint. Override with
// FEED_WRITE_TOKEN_API_URL only for non-prod / dev stages.
const DEFAULT_API_URL = "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod/feed";

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const apiUrl = process.env["FEED_WRITE_TOKEN_API_URL"] || DEFAULT_API_URL;
const token = process.env["FEED_WRITE_TOKEN"];
const agent = arg("agent");
const bodyFile = arg("body-file");
const skillVersion = arg("skill-version");

if (!token) { console.error("post.mjs: FEED_WRITE_TOKEN env var is required (from credentials['workforce.feed_write_token'])"); process.exit(1); }
if (!agent) { console.error("post.mjs: --agent <slug> is required"); process.exit(1); }
if (!bodyFile) { console.error("post.mjs: --body-file <path> is required"); process.exit(1); }
if (apiUrl.startsWith("TODO_")) { console.error("post.mjs: DEFAULT_API_URL is still a scaffold placeholder — set the real endpoint"); process.exit(1); }

let body;
try {
